:is(.block-language-nimble, .block-language-nimble-spell, .block-language-nimble-item, .block-language-5e, .block-language-5e-spell, .block-language-5e-item, .ev-content-block):hover > button.nimble-block-edit, button.nimble-block-edit:focus-visible { opacity: 1; }
