.nimble-issues-list { display: flex; flex-direction: column; gap: 0.5rem; margin-top: 0.4rem; padding: 0.6rem 0.75rem; border: 1px solid var(--background-modifier-border); border-radius: var(--nimble-radius); background: var(--background-secondary); }
