.nimble-issue code.nimble-issue-line { align-self: flex-start; max-width: 100%; overflow-wrap: anywhere; white-space: pre-wrap; font-size: var(--font-ui-smaller); padding: 0.1rem 0.4rem; color: var(--text-muted); background: var(--background-primary); border-radius: var(--radius-s); }
.nimble-issue-line mark { color: var(--text-normal); background: color-mix(in srgb, var(--color-yellow) 35%, transparent); border-radius: 2px; padding: 0 1px; }
