.notice .ev-roll-toast .ev-roll-tag { align-self: center; display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 3px; background: rgb(255 255 255 / 0.18); font: 800 11px/normal var(--ev-font-ui, var(--font-interface)); letter-spacing: 0.06em; }
.notice .ev-roll-toast.is-crit .ev-roll-tag { background: var(--ev-red, var(--color-red)); color: #fff; }
