/* ============================================
   GM MAP (```nimble-map)
   ============================================ */

/* In the look of the campaign's game (map-block.ts applies .ev-sys-<id>): the game's paper around the map, its
   toolbar as compact pill buttons (the one pressed takes the game's colour, a full tint), pins and tokens in its
   colours, the tray in its type. Nimble: charcoal markers, monsters as charcoal discs, heroes on parchment. 5e: the
   book's oxblood with a gold ring. */
.nimble-map { margin: 0.75rem 0; border: 1px solid var(--ev-line, var(--background-modifier-border)); border-radius: var(--ev-r-lg, var(--nimble-radius)); overflow: hidden; background: var(--ev-surface, var(--background-secondary)); color: var(--ev-text, var(--text-normal)); font-family: var(--ev-font-ui, var(--font-interface)); }
.nimble-map-toolbar { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--ev-line, var(--background-modifier-border)); }
.nimble-map button.nimble-map-btn { height: 30px; padding: 0 11px; border-radius: var(--ev-r-md, 6px); border: 1px solid var(--ev-line-strong, var(--background-modifier-border)); background: var(--ev-surface, var(--interactive-normal)); box-shadow: none; color: var(--ev-text, var(--text-normal)); font: 600 13px/normal var(--ev-font-ui, var(--font-interface)); --ev-pill-icon: 15px; --ev-pill-gap: 6px; }
.nimble-map button.nimble-map-btn:hover { background: var(--ev-surface-2, var(--background-modifier-hover)); }
.nimble-map button.nimble-map-btn.is-icon-only { width: 30px; padding: 0; }
.nimble-map button.nimble-map-btn.is-active { border-color: var(--ev-accent, var(--interactive-accent)); background: var(--ev-accent, var(--interactive-accent)); color: var(--ev-on-accent, var(--text-on-accent)); }
.nimble-map button.nimble-map-btn.is-active:hover { background: var(--ev-accent-hover, var(--interactive-accent-hover)); }
.nimble-map button.nimble-map-zoom { color: var(--ev-text-2, var(--icon-color)); }
.nimble-map button.nimble-map-zoom svg { width: 17px; height: 17px; }
.nimble-map-spacer { flex: 1; }
.nimble-map-hint { padding: 5px 10px; font: 500 12.5px/18px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text-2, var(--text-muted)); background: var(--ev-surface-2, var(--background-primary-alt)); border-bottom: 1px solid var(--ev-line, var(--background-modifier-border)); }
.nimble-map-body { display: flex; }
.nimble-map-viewport { position: relative; flex: 1; height: 480px; overflow: hidden; background: #111; cursor: grab; touch-action: none; resize: vertical; outline: none; }
.nimble-map-viewport:active { cursor: grabbing; }
.nimble-map-viewport.mode-add { cursor: crosshair; }
.nimble-map-viewport:focus-visible { box-shadow: inset 0 0 0 2px var(--ev-accent, var(--interactive-accent)); }
.nimble-map-stage { position: absolute; left: 0; top: 0; transform-origin: 0 0; --nimble-map-inv: 1; }
.nimble-map .nimble-map-viewport .nimble-map-stage img { display: block; max-width: none; width: 100%; height: 100%; user-select: none; pointer-events: none; margin: 0; }
.nimble-map-grid { position: absolute; inset: 0; pointer-events: none; background-image: linear-gradient(to right, rgba(0,0,0,.35) 1px, transparent 1px), linear-gradient(to bottom, rgba(0,0,0,.35) 1px, transparent 1px); }
.nimble-map-layer { position: absolute; inset: 0; pointer-events: none; }
.nimble-map-pin, .nimble-map-token { position: absolute; pointer-events: auto; }
.nimble-map-pin { width: 0; height: 0; cursor: pointer; z-index: 2; }
/* Pins: a marker in the game's colour, its kind's icon in it, a ring of the paper; the label a dark tag above. */
.nimble-map { --pin: var(--ev-bar, var(--interactive-accent)); --pin-ring: var(--ev-surface, #fff); --pin-ink: var(--ev-on-bar, #fff); }
.nimble-map.ev-sys-dnd5e { --pin: var(--ev-accent); --pin-ring: var(--x5-gold-hi); --pin-ink: var(--ev-on-accent); }
.nimble-map-pin-inner { position: absolute; left: 0; top: 0; display: flex; flex-direction: column; align-items: center; transform: translate(-50%, -100%) scale(var(--nimble-map-inv)); transform-origin: 50% 100%; }
.nimble-map-pin-icon { display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); background: var(--pin); border: 2px solid var(--pin-ring); box-shadow: 0 2px 6px rgba(0,0,0,.45); }
.nimble-map-pin-icon svg { width: 15px; height: 15px; color: var(--pin-ink); transform: rotate(45deg); }
.nimble-map-pin-label { order: -1; display: flex; align-items: center; height: 19px; margin-bottom: 3px; padding: 0 6px; border-radius: var(--ev-r-chip, 3px); background: rgb(20 18 16 / 0.82); color: #fff; font: 700 12px/normal var(--ev-font-ui, var(--font-interface)); white-space: nowrap; }
.nimble-map.ev-sys-nimble .nimble-map-pin-label { font: 700 12.5px/normal var(--ev-font-display); letter-spacing: 0.02em; }
.nimble-map.ev-sys-dnd5e .nimble-map-pin-label { background: rgb(42 10 6 / 0.86); font: 600 14px/normal var(--ev-font-display); font-variant: small-caps; letter-spacing: 0.03em; }
.nimble-map .pin-label-short { display: none; }
/* Zoomed out, numbered labels ("N5. Gate") shrink to their key until you hover or focus the pin.
   Labels without a key stay whole: Show pin labels always shows something. */
.nimble-map.is-zoomed-out:not(.hide-labels) .nimble-map-pin.has-key:not(:hover, :focus-visible) .pin-label-full { display: none; }
.nimble-map.is-zoomed-out:not(.hide-labels) .nimble-map-pin.has-key:not(:hover, :focus-visible) .pin-label-short { display: inline; }
.nimble-map.is-zoomed-out .nimble-map-pin:is(:hover, :focus-visible) .nimble-map-pin-label { display: flex; }
.nimble-map-pin:is(:hover, :focus-visible) { z-index: 5; }
.nimble-map.hide-labels .nimble-map-pin-label { display: none; }
.nimble-map.hide-labels .nimble-map-pin:hover .nimble-map-pin-label { display: flex; }
.nimble-map-pin:hover .nimble-map-pin-icon, .nimble-map-pin:focus-visible .nimble-map-pin-icon { filter: brightness(1.15); box-shadow: 0 0 0 3px rgba(255,255,255,.5); }
.nimble-map-pin.is-unlinked .nimble-map-pin-icon { opacity: 0.85; border-style: dashed; }
.nimble-map-pin.is-dragging { cursor: grabbing; z-index: 5; }
/* A kind's colour, from the game's own: danger and encounters red (Nimble's HP red, 5e's danger), treasure ochre or gold. */
.nimble-map-pin:is(.kind-encounter, .kind-danger) { --pin: var(--ev-red, var(--ev-danger-text, #c0504d)); }
.nimble-map-pin.kind-treasure { --pin: var(--ev-ochre, var(--ev-gold, #c89a2c)); }
.nimble-map-pin.kind-secret { --pin: #2a2724; }
.nimble-map.ev-sys-dnd5e .nimble-map-pin:is(.kind-encounter, .kind-danger) { --pin: var(--x5-banner-a); }
.nimble-map.ev-sys-dnd5e .nimble-map-pin.kind-treasure { --pin: var(--ev-gold); }
/* Tokens: monsters in the game's dark (Nimble's charcoal, 5e's oxblood) with light initials, heroes on its paper;
   a legendary monster's ring in ochre or gold. Done: faded; down: grey. */
.nimble-map-token { width: 0; height: 0; z-index: 3; cursor: grab; }
.nimble-map-token .nimble-map-token-text, .nimble-map-token.in-tray .nimble-map-token-text { display: flex; align-items: center; justify-content: center; width: 30px; height: 30px; border-radius: 50%; font: 700 12px/1 var(--ev-font-num, var(--font-interface)); letter-spacing: 0.02em; color: var(--ev-on-bar, #fff); background: var(--ev-bar, #4b4743); border: 2px solid var(--ev-surface, #fff); box-shadow: 0 2px 5px rgba(0,0,0,.5); }
.nimble-map.ev-sys-dnd5e .nimble-map-token .nimble-map-token-text { font: 600 13px/1 var(--ev-font-display); color: var(--ev-on-accent); background: var(--ev-accent); border-color: var(--x5-gold-hi); }
.nimble-map-tokens .nimble-map-token .nimble-map-token-text { position: absolute; left: 0; top: 0; transform: translate(-50%, -50%) scale(var(--nimble-map-inv)); }
.nimble-map .nimble-map-token.role-hero .nimble-map-token-text { background: var(--ev-surface, #fff); color: var(--ev-text, #111); border-color: var(--ev-bar, #4b4743); }
.nimble-map.ev-sys-dnd5e .nimble-map-token.role-hero .nimble-map-token-text { background: var(--ev-surface); color: var(--ev-accent-text); border-color: var(--ev-accent); }
.nimble-map .nimble-map-token.role-minion .nimble-map-token-text { width: 26px; height: 26px; font-size: 11px; }
.nimble-map .nimble-map-token.role-legendary .nimble-map-token-text { border-color: var(--ev-ochre, var(--x5-gold, #c89a2c)); box-shadow: 0 0 0 2px rgb(0 0 0 / 0.35), 0 2px 5px rgba(0,0,0,.5); }
.nimble-map.ev-sys-dnd5e .nimble-map-token.role-legendary .nimble-map-token-text { border-color: var(--x5-gold); }
.nimble-map-token.is-done { opacity: 0.6; }
.nimble-map-token.is-down { opacity: 0.35; filter: grayscale(1); }
.nimble-map-tray { width: 168px; flex-shrink: 0; border-left: 1px solid var(--ev-line, var(--background-modifier-border)); padding: 8px; overflow: auto; max-height: 480px; display: flex; flex-direction: column; gap: 6px; background: var(--ev-surface, var(--background-secondary)); }
.nimble-map-tray-title { font: 600 12px/16px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text-2, var(--text-muted)); }
.nimble-map-tray-empty { font: 500 12.5px/18px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text-2, var(--text-muted)); }
.nimble-map-token.in-tray { position: static; width: auto; height: auto; display: flex; align-items: center; gap: 8px; min-height: 36px; padding: 2px 4px; border-radius: var(--ev-r-md, 6px); cursor: grab; touch-action: none; }
.nimble-map-token.in-tray:hover { background: var(--ev-surface-2, var(--background-modifier-hover)); }
.nimble-map-token.in-tray .nimble-map-token-text { flex: none; }
.nimble-map-token-name { min-width: 0; font: 600 13px/17px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text, var(--text-normal)); overflow-wrap: anywhere; }
.nimble-map.ev-sys-nimble .nimble-map-token-name { font: italic 800 14px/17px var(--ev-font-name); }
.nimble-map.ev-sys-dnd5e .nimble-map-token-name { font: 600 15px/17px var(--ev-font-display); font-variant: small-caps; color: var(--ev-accent-text); letter-spacing: 0.02em; }
.nimble-map-token-ghost { position: fixed; z-index: var(--layer-popover); transform: translate(-50%, -50%); pointer-events: none; padding: 3px 10px; border-radius: 999px; background: var(--interactive-accent); color: var(--text-on-accent); font-size: 0.8rem; font-weight: 600; }

/* ============================================
   INLINE MONSTER REFERENCES  (`nimble:Name`, `5e:Name`)
   A split pill: [level | name | +], [icon | name], built by refPill() in core/inline-refs.ts for every
   game. Its segments stretch to the pill's height and centre their own content, so it isn't in the
   shared pill rule; e2e/align.mjs measures it all the same.
   ============================================ */

.nimble-inline-ref {
	--ref-tint: var(--interactive-accent);
	display: inline-flex;
	align-items: stretch;
	height: 1.5em;
	max-width: 100%;
	/* An inline-flex box's baseline is its first item's text baseline, so the
	   name lines up with the surrounding sentence instead of sinking below it. */
	vertical-align: baseline;
	/* Baseline alignment leaves the box optically low; lift it ~2px without changing line spacing. */
	position: relative;
	top: -0.12em;
	margin: 0 0.1em;
	border-radius: 999px;
	border: 1px solid color-mix(in srgb, var(--ref-tint) 32%, transparent);
	background: color-mix(in srgb, var(--ref-tint) 9%, var(--background-primary));
	font-size: 0.92em;
	line-height: normal;
	overflow: hidden;
	transition: border-color 0.12s, background 0.12s, box-shadow 0.12s;
}
/* Every pill sits on the line the same way, whatever comes first. An inline-flex box takes its baseline from
   its first item: a monster's level badge is text, but a spell's icon isn't, and the browser then used the
   icon's bottom edge and the pill rode ~3px high. This zero-width first item, set like the level badge and
   centred, gives every pill the badge's baseline. */
.nimble-inline-ref::before { content: "\200b"; align-self: center; width: 0; overflow: hidden; font-size: 0.78em; font-weight: 700; }
.nimble-inline-ref:hover { border-color: color-mix(in srgb, var(--ref-tint) 60%, transparent); box-shadow: 0 1px 4px color-mix(in srgb, var(--ref-tint) 18%, transparent); }
.nimble-inline-ref.role-legendary { --ref-tint: var(--nimble-legendary); }
.nimble-inline-ref.role-minion { --ref-tint: var(--nimble-minion); }

.nimble-inline-level {
	display: inline-flex;
	align-items: center;
	padding: 0 0.45em 0 0.6em;
	font-size: 0.78em;
	font-weight: 700;
	font-variant-numeric: tabular-nums;
	letter-spacing: 0.02em;
	color: color-mix(in srgb, var(--ref-tint) 80%, var(--text-normal));
	background: color-mix(in srgb, var(--ref-tint) 14%, transparent);
	border-right: 1px solid color-mix(in srgb, var(--ref-tint) 22%, transparent);
	cursor: default;
}

.nimble-inline-name {
	display: inline-flex;
	align-items: center;
	padding: 0 0.6em;
	color: var(--text-normal);
	font-weight: 600;
	text-decoration: none;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	cursor: pointer;
}
.nimble-inline-name:hover { color: color-mix(in srgb, var(--ref-tint) 75%, var(--text-normal)); }
/* Obsidian underlines links on hover (a:hover); the pill never does. */
.nimble-inline-ref .nimble-inline-name, .nimble-inline-ref .nimble-inline-name:hover { text-decoration: none; }

.nimble-inline-ref .nimble-inline-add-btn {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 1.75em;
	height: auto;
	min-height: 0;
	margin: 0;
	padding: 0 0.1em 0 0;
	border: none;
	border-left: 1px solid color-mix(in srgb, var(--ref-tint) 22%, transparent);
	border-radius: 0;
	box-shadow: none;
	background: transparent;
	color: color-mix(in srgb, var(--ref-tint) 85%, var(--text-normal));
	cursor: pointer;
	transition: background 0.12s, color 0.12s;
}
.nimble-inline-ref .nimble-inline-add-btn:is(:hover, :focus-visible, .mobile-tap) { box-shadow: none; }
.nimble-inline-ref .nimble-inline-add-btn svg { width: 0.95em; height: 0.95em; stroke-width: 2.6; }
.nimble-inline-ref .nimble-inline-add-btn:hover { background: var(--ref-tint); color: #fff; }
.nimble-inline-ref .nimble-inline-add-btn:focus-visible { outline: none; background: var(--ref-tint); color: #fff; }

.nimble-inline-ref.nimble-inline-unresolved {
	--ref-tint: var(--text-faint);
	border-style: dashed;
	background: transparent;
}
.nimble-inline-name.unresolved { color: var(--text-muted); font-weight: 500; cursor: default; }
.nimble-inline-unknown {
	display: inline-flex;
	align-items: center;
	padding: 0 0.55em;
	font-size: 0.8em;
	font-weight: 700;
	color: var(--text-error);
	border-left: 1px dashed var(--background-modifier-border);
}

/* Compendium references (`nimble:spell:Name`, `5e:spell:Fireball`, `nimble:condition:Dazed`…): [icon | name], tinted by kind. */
.nimble-inline-ref.is-compendium:is(.kind-item, .kind-equipment) { --ref-tint: #b8703a; }
.nimble-inline-ref.is-compendium.kind-spell { --ref-tint: #3d7fe0; }
.nimble-inline-ref.is-compendium:is(.kind-feature, .kind-boon, .kind-feat) { --ref-tint: #a35fd6; }
.nimble-inline-ref.is-compendium:is(.kind-class, .kind-subclass, .kind-ancestry, .kind-background, .kind-species) { --ref-tint: #24a06b; }
.nimble-inline-ref.is-compendium.kind-condition { --ref-tint: #d0613c; }
.nimble-inline-kind {
	display: inline-flex;
	align-items: center;
	padding: 0 0.3em 0 0.5em;
	color: color-mix(in srgb, var(--ref-tint) 85%, var(--text-normal));
	background: color-mix(in srgb, var(--ref-tint) 14%, transparent);
	border-right: 1px solid color-mix(in srgb, var(--ref-tint) 22%, transparent);
	cursor: default;
}
.nimble-inline-kind svg { display: block; width: 0.95em; height: 0.95em; stroke-width: 2.2; }
/* In a game's look (refPill's `system`): one anatomy, each game's colour. The tint is the game's own (its
   --interactive-accent: charcoal in Nimble, oxblood in 5e), on the game's paper; a kind takes the colour the game
   gives it (Nimble: spells blue as mana, items ochre; 5e: items gold, the rest the book's red). */
.nimble-inline-ref:is(.ev-sys-nimble, .ev-sys-dnd5e) { border-color: color-mix(in srgb, var(--ref-tint) 30%, var(--ev-line)); }
.nimble-inline-ref.ev-sys-nimble:is(.role-legendary, .role-minion, .role-regular, .is-lore) { --ref-tint: var(--ev-accent); }
.nimble-inline-ref.ev-sys-nimble.is-compendium[class*="kind-"] { --ref-tint: var(--ev-accent); }
.nimble-inline-ref.ev-sys-nimble.is-compendium.kind-spell { --ref-tint: var(--ev-mana); }
.nimble-inline-ref.ev-sys-nimble.is-compendium:is(.kind-item, .kind-equipment) { --ref-tint: var(--ev-ochre); }
.nimble-inline-ref.ev-sys-dnd5e.is-compendium[class*="kind-"] { --ref-tint: var(--ev-accent); }
.nimble-inline-ref.ev-sys-dnd5e.is-compendium:is(.kind-item, .kind-equipment) { --ref-tint: var(--ev-gold); }
.nimble-inline-ref:is(.ev-sys-nimble, .ev-sys-dnd5e).nimble-inline-unresolved { --ref-tint: var(--ev-text-2); }
/* 5e's oxblood is a fill in the dark theme, too dim as type on the pill (3.9:1): a level or kind it tints reads in the game's accent text. */
.nimble-inline-ref.ev-sys-dnd5e:not(.kind-item, .kind-equipment, .nimble-inline-unresolved) :is(.nimble-inline-level, .nimble-inline-kind) { color: var(--ev-accent-text); }
.nimble-inline-ref.ev-sys-nimble .nimble-inline-level { font-family: var(--ev-font-num); font-size: 0.86em; }
.nimble-inline-ref:is(.ev-sys-nimble, .ev-sys-dnd5e) .nimble-inline-add-btn:is(:hover, :focus-visible) { color: var(--ev-on-accent); }


.nimble-encounter-block .encounter-block-meta, .nimble-encounter-block .encounter-block-notes { font-size: 0.8rem; color: var(--text-muted); }
.nimble-encounter-block .encounter-block-notes { font-style: italic; margin-top: 0.25rem; }
.nimble-encounter-block .encounter-block-empty { color: var(--text-muted); font-size: 0.85rem; }
.encounter-block-warning { font-size: 0.8rem; color: var(--nimble-warn); margin-top: 0.2rem; }
.encounter-block-warning::before { content: "⚠ "; }
.nimble-encounter-block .encounter-block-actions { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.6rem; }
.nimble-encounter-block .encounter-block-actions button { display: inline-flex; align-items: center; gap: 0.3rem; }
.nimble-encounter-block .encounter-block-actions svg { width: 14px; height: 14px; }

.nimble-difficulty { font-size: 0.7rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; padding: 0.1rem 0.5rem; border-radius: 4px; white-space: nowrap; }
.diff-trivial { background: var(--background-modifier-hover); color: var(--text-muted); }
.diff-easy { background: rgba(76, 175, 109, 0.18); color: #3f9d5d; }
.diff-medium { background: rgba(201, 182, 72, 0.2); color: #a8922a; }
.diff-hard { background: rgba(224, 138, 65, 0.2); color: #c9702a; }
.diff-deadly { background: rgba(224, 93, 93, 0.2); color: #d24c4c; }
.diff-very-deadly { background: rgba(208, 64, 138, 0.2); color: #c23a82; }


/* Settings: party rows */
/* Settings: party table */
.nimble-party-table { display: grid; gap: 0.3rem; margin: 0.5rem 0 0.6rem; }
.nimble-party-head, .nimble-party-row { display: grid; grid-template-columns: minmax(7rem, 1.4fr) minmax(6rem, 1.2fr) 3.6rem 4.2rem 4.2rem 4.6rem 2rem; gap: 0.4rem; align-items: center; }
.nimble-party-head { font-size: 0.72rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); padding: 0 0.15rem; }
.nimble-party-row input { width: 100%; min-width: 0; }
.nimble-party-row input.nimble-party-num { text-align: center; }
.nimble-party-row.is-sheet .nimble-party-value { display: block; padding: 0 0.3rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-muted); }
.nimble-party-row.is-sheet .field-name .nimble-party-value { color: var(--text-normal); font-weight: 600; }
.nimble-party-row.is-sheet :is(.field-level, .field-max-hp, .field-defense, .field-max-wounds) .nimble-party-value { text-align: center; }
.nimble-party-empty { color: var(--text-muted); font-size: 0.85rem; padding: 0.3rem 0; }
.nimble-party-actions { display: flex; gap: 0.5rem; margin-bottom: 0.8rem; }
.nimble-party-actions button { display: inline-flex; align-items: center; gap: 0.35rem; }
.nimble-party-actions svg { width: 15px; height: 15px; }
.nimble-party-modal { width: min(760px, 94vw); }

/* The party editor as a game dialog (core/party.ts, PartyModal): column heads as the game's labels, the name in its
   name type, numbers in its figures, Add hero and Level up as the dialog's buttons. */
.modal.nimble-party-modal.ev-dialog { width: min(780px, 96vw); }
.ev-dialog .nimble-party-head > div { font: 700 12px/normal var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-dialog.ev-sys-nimble .nimble-party-head > div { font: 700 12.5px/normal var(--ev-font-display); letter-spacing: 0.07em; }
.ev-dialog.ev-sys-dnd5e .nimble-party-head > div { font: 600 15px/normal var(--ev-font-display); font-variant: small-caps; text-transform: none; letter-spacing: 0.04em; color: var(--ev-accent-text); }
.ev-dialog .nimble-party-row input { height: 36px; border-radius: var(--ev-r-md); font: 500 14px/normal var(--ev-font-ui); }
.ev-dialog .nimble-party-row input.nimble-party-num { font: 700 16px/normal var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; }
.ev-dialog.ev-sys-nimble .nimble-party-row .field-name input { font: italic 800 15.5px/normal var(--ev-font-name); }
.ev-dialog.ev-sys-dnd5e .nimble-party-row .field-name input { font: 600 16px/normal var(--ev-font-display); font-variant: small-caps; letter-spacing: 0.02em; }
.ev-dialog .nimble-party-row button.nimble-party-del { color: var(--ev-text-2); }
.ev-dialog .nimble-party-actions { gap: 8px; margin: 2px 0 0; }
.ev-dialog .nimble-party-actions button.nimble-party-btn { height: 40px; padding: 0 14px; border-radius: var(--ev-r-md); border: 1px solid var(--ev-line-strong); background: var(--ev-surface); box-shadow: none; color: var(--ev-text); font: 600 14px/normal var(--ev-font-ui); --ev-pill-icon: 17px; --ev-pill-gap: 7px; }
.ev-dialog .nimble-party-actions button.nimble-party-btn:hover { background: var(--ev-surface-2); }
.ev-dialog .nimble-party-actions button.nimble-party-btn.mod-cta { border-color: var(--ev-accent); background: var(--ev-accent); color: var(--ev-on-accent); }
.ev-dialog .nimble-party-actions button.nimble-party-btn.mod-cta:hover { background: var(--ev-accent-hover); }
.nimble-bestiary .bestiary-attribution { font-size: 0.74rem; color: var(--text-muted); border-top: 1px solid var(--background-modifier-border); padding-top: 0.4rem; display: grid; gap: 0.3rem; }
.nimble-bestiary .bestiary-attribution summary { cursor: pointer; color: var(--text-faint); }
.nimble-bestiary .bestiary-attribution a { color: var(--text-muted); }

/* ============================================
   SLASH COMMANDS AND NIMBLE CALLOUTS
   ============================================ */

.suggestion-container .suggestion-item.nimble-slash-item { display: flex; align-items: center; gap: 10px; }
/* The menu stays Obsidian's; each row carries the note's game look (core/slash.ts): its chip for the icon, its
   accent on the chosen row, its type for names (commands stay in the interface face), its tags for badges. */
.nimble-slash-icon { flex-shrink: 0; display: flex; align-items: center; justify-content: center; width: 30px; height: 30px; border-radius: var(--ev-r-sm, 6px); background: var(--ev-chip-bg, var(--background-modifier-hover)); color: var(--ev-text-2, var(--text-muted)); }
.nimble-slash-icon svg { width: 16px; height: 16px; }
.suggestion-item.is-selected .nimble-slash-icon { background: var(--ev-accent, var(--interactive-accent)); color: var(--ev-on-accent, var(--text-on-accent)); }
.nimble-slash-text { flex: 1; min-width: 0; }
.nimble-slash-title { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.nimble-slash-item.ev-sys-nimble .nimble-slash-title:not(.is-command) { font: 700 15.5px/20px var(--ev-font-display); }
.nimble-slash-item.ev-sys-dnd5e .nimble-slash-title:not(.is-command) { font: 600 16.5px/20px var(--ev-font-display); letter-spacing: 0.01em; }
.nimble-slash-detail { font-size: 0.78em; color: var(--ev-text-2, var(--text-muted)); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* A badge is a tag: dark, white text; a difficulty keeps its colour as a dot, as the encounter blocks show it. */
.nimble-slash-badge { flex-shrink: 0; display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: var(--ev-r-chip, 4px); background: var(--ev-bar, var(--ev-accent)); color: var(--ev-on-bar, var(--ev-on-accent)); font: 700 10.5px/normal var(--ev-font-ui, var(--font-interface)); letter-spacing: 0.05em; text-transform: uppercase; white-space: nowrap; }
.nimble-slash-item.ev-sys-dnd5e .nimble-slash-badge { background: var(--ev-accent); color: var(--ev-on-accent); }
/* A muted badge says what a row is (Spell, SRD): quiet small capitals, as Spotlight's rows say it. */
.suggestion-item .nimble-slash-badge.is-muted { padding: 0; background: transparent; color: var(--ev-text-2, var(--text-muted)); }

.callout[data-callout="nimble-read"] { --callout-color: 91, 141, 239; --callout-icon: lucide-book-open-text; font-style: italic; }
.callout[data-callout="nimble-read"] .callout-title { font-style: normal; }
.callout[data-callout="nimble-secret"] { --callout-color: 192, 80, 77; --callout-icon: lucide-eye-off; }
.callout[data-callout="nimble-trap"] { --callout-color: 217, 163, 60; --callout-icon: lucide-triangle-alert; }
.callout[data-callout="nimble-npc"] { --callout-color: 63, 143, 90; --callout-icon: lucide-user-round; }
.callout[data-callout="nimble-condition"] { --callout-color: 142, 91, 208; --callout-icon: lucide-activity; }
.nimble-slash-badge[class*="diff-"]::before { content: ""; flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--diff-dot, currentColor); }
.nimble-slash-badge:is(.diff-easy, .diff-low) { --diff-dot: #6cc48a; }
.nimble-slash-badge:is(.diff-medium, .diff-moderate) { --diff-dot: #e3cd5a; }
.nimble-slash-badge:is(.diff-hard, .diff-high) { --diff-dot: #f0a05a; }
.nimble-slash-badge.diff-deadly { --diff-dot: #ff7a6b; }
.nimble-slash-badge.diff-very-deadly { --diff-dot: #f06aac; }
.nimble-slash-badge.diff-trivial { --diff-dot: var(--ev-line-strong, var(--background-modifier-border)); }

/* ============================================
   ENCOUNTER CHIPS: one pill = [− 3× +] [lvl] [name]
   ============================================ */

.nimble-encounter-block .encounter-block-monsters { display: flex; flex-wrap: wrap; align-items: center; gap: 0.45rem; }
.encounter-chip {
	--ref-tint: var(--interactive-accent);
	display: inline-flex;
	align-items: stretch;
	height: 1.65em;
	font-size: 0.92em;
	border-radius: 999px;
	border: 1px solid color-mix(in srgb, var(--ref-tint) 32%, transparent);
	background: color-mix(in srgb, var(--ref-tint) 9%, var(--background-primary));
	overflow: hidden;
	transition: border-color 0.12s, box-shadow 0.12s;
}
.encounter-chip:focus-within { border-color: color-mix(in srgb, var(--ref-tint) 60%, transparent); }
.encounter-chip.role-legendary { --ref-tint: var(--nimble-legendary); }
.encounter-chip.role-minion { --ref-tint: var(--nimble-minion); }
.encounter-chip.role-unknown { --ref-tint: var(--text-faint); border-style: dashed; background: transparent; }

/* The monster pill inside the chip loses its own frame. */
.encounter-chip .nimble-inline-ref {
	height: auto;
	font-size: 1em;
	top: 0;
	margin: 0;
	border: none;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
	border-left: 1px solid color-mix(in srgb, var(--ref-tint) 22%, transparent);
}
.encounter-chip .nimble-inline-ref:hover { box-shadow: none; }
.encounter-chip .nimble-inline-ref .nimble-inline-add-btn { display: none; }
.encounter-chip .nimble-inline-name { padding-right: 0.75em; }


/* Difficulty chip opens the balancer */
.nimble-difficulty.is-button { display: inline-flex; align-items: center; gap: 0.35rem; border: none; box-shadow: none; height: auto; cursor: pointer; font-family: inherit; }
.nimble-difficulty.is-button:hover { filter: brightness(0.95); box-shadow: 0 0 0 1px currentColor inset; }
.nimble-difficulty .diff-chevron { display: inline-flex; opacity: 0.75; }
.nimble-difficulty .diff-chevron svg { width: 12px; height: 12px; }
.encounter-block-meta .encounter-party-link, .encounter-block-meta .encounter-party-link:hover { text-decoration: none; }
.encounter-block-meta .encounter-party-link { color: var(--text-muted); border-bottom: 1px dotted currentColor; }
.encounter-block-meta .encounter-party-link:hover { color: var(--text-accent); }


/* Buttons styled as difficulty chips keep their colours over Obsidian's button styles. */
.nimble-difficulty.is-button.diff-trivial { background: var(--background-modifier-hover); color: var(--text-muted); }
.nimble-difficulty.is-button.diff-easy { background: rgba(76, 175, 109, 0.18); color: #3f9d5d; }
.nimble-difficulty.is-button.diff-medium { background: rgba(201, 182, 72, 0.2); color: #a8922a; }
.nimble-difficulty.is-button.diff-hard { background: rgba(224, 138, 65, 0.2); color: #c9702a; }
.nimble-difficulty.is-button.diff-deadly { background: rgba(224, 93, 93, 0.2); color: #d24c4c; }
.nimble-difficulty.is-button.diff-very-deadly { background: rgba(208, 64, 138, 0.2); color: #c23a82; }

/* ============================================
   TOUCH, PHONE AND TABLET
   Bottom sheets, the HP keypad, finger-sized targets and narrow layouts.
   ============================================ */

/* Bottom sheets (phones): popovers and the stat block preview */
.nimble-popover.is-sheet, .nimble-hover-preview.is-sheet {
	left: 0;
	right: 0;
	top: auto;
	bottom: 0;
	width: 100%;
	max-width: none;
	max-height: 78vh;
	border-radius: 14px 14px 0 0;
	border-bottom: none;
	padding-bottom: calc(0.8rem + env(safe-area-inset-bottom, 0px) + var(--mobile-toolbar-height, 0px));
	animation: nimble-sheet-in 0.18s ease-out;
	overscroll-behavior: contain;
}
.nimble-popover.is-sheet { padding-left: 1rem; padding-right: 1rem; font-size: 0.95rem; }
.nimble-hover-preview.is-sheet .hover-preview-bar { font-size: 0.85rem; font-weight: 600; color: var(--text-normal); padding: 0.1rem 0.4rem 0.3rem 1rem; }
.nimble-hover-preview.is-sheet .hover-preview-close { width: 2.5rem; height: 2.5rem; }
.sheet-handle { width: 2.4rem; height: 4px; border-radius: 2px; background: var(--background-modifier-border-hover, var(--text-faint)); margin: 0.45rem auto 0.5rem; flex-shrink: 0; }
.nimble-hover-preview.is-sheet .sheet-handle { position: sticky; top: 0; z-index: 2; margin: 0 auto; padding: 0; height: 18px; width: 100%; background: var(--background-primary); }
.nimble-hover-preview.is-sheet .sheet-handle::after { content: ""; display: block; width: 2.4rem; height: 4px; margin: 7px auto; border-radius: 2px; background: var(--text-faint); }
.nimble-hover-preview.is-sheet .hover-preview-bar { top: 18px; }
@keyframes nimble-sheet-in { from { transform: translateY(24px); opacity: 0.4; } to { transform: none; opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .nimble-popover.is-sheet, .nimble-hover-preview.is-sheet { animation: none; } }

/* Group attack: how many minions attack */
.nimble-encounter-tracker .group-attack-all, .group-attack-all { width: 100%; margin-bottom: 0.4rem; }

/* Map pin / token cards (touch) */
.nimble-pin-card .pin-card-actions, .nimble-popover .pin-card-actions { display: flex; gap: 0.4rem; margin-top: 0.6rem; flex-wrap: wrap; }
.nimble-popover .pin-card-actions button { flex: 1; }

/* HP keypad (core/tracker/hp-pad.ts): beside the button that opened it, a bottom sheet on phones. Drawn in the
   game's look (.ev-sys-<id> on the popover): who and where it lands on the left, the amount on the right, the
   modes, the players' quiet chips (Defend, Interpose), the keys, Cancel and Apply. */
.nimble-popover.nimble-hp-pad {
	--calc-color: var(--ev-danger-text, var(--text-error));
	box-sizing: border-box;
	max-width: calc(100vw - 16px);
	padding: 10px 12px 12px;
	display: flex; flex-direction: column; gap: 10px;
	outline: none;
	background: var(--ev-surface, var(--background-primary));
	color: var(--ev-text, var(--text-normal));
	font-family: var(--ev-font-ui, var(--font-interface));
}
/* As a phone bottom sheet it spans the full width (the cap above would leave a gap on the right). */
.nimble-popover.nimble-hp-pad.is-sheet { max-width: none; }
.nimble-hp-pad[data-mode="heal"] { --calc-color: var(--ev-ok, var(--color-green)); }
