.nimble-hp-pad .hp-pad-modes { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 0; padding: 3px; border-radius: var(--ev-r-md, 8px); background: var(--ev-surface-2, var(--background-modifier-border)); --seg-pad: 3px; --seg-gap: 0px; --seg-color: var(--ev-surface, var(--background-primary)); }
