.nimble-hp-pad .hp-pad-choice { height: 28px; padding: 0 10px; border-radius: var(--ev-r-md, 6px); border: 1px solid var(--ev-line-strong, var(--background-modifier-border)); background: var(--ev-surface, var(--background-primary)); box-shadow: none; font: 500 13px/normal var(--ev-font-ui, var(--font-interface)); color: var(--ev-text, var(--text-normal)); }
.nimble-hp-pad .hp-pad-choice.is-active { background: var(--ev-accent, var(--interactive-accent)); border-color: var(--ev-accent, var(--interactive-accent)); color: var(--ev-on-accent, var(--text-on-accent)); }
.nimble-hp-pad .hp-pad-toggles { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: 6px; }
