.nimble-hp-pad .hp-pad-keys button { height: 44px; padding: 0; border: 0; border-radius: var(--ev-r-md, 6px); box-shadow: none; background: var(--ev-surface-2, var(--background-secondary)); color: var(--ev-text, var(--text-normal)); font: 500 20px/normal var(--ev-font-num, var(--font-interface)); font-variant-numeric: tabular-nums lining-nums; }
