.nimble-hp-pad .hp-pad-apply:disabled { background: var(--ev-surface-2, var(--background-modifier-hover)); border-color: var(--ev-line, var(--background-modifier-border)); color: var(--ev-text-2, var(--text-faint)); cursor: default; }
