/* Add monster dialog */
.nimble-add-monster-modal { width: min(640px, 96vw); }
.nimble-add-monster-modal .nimble-add-filters { display: flex; flex-wrap: wrap; gap: 0.3rem; padding: 0.45rem 0.75rem 0.5rem; border-bottom: 1px solid var(--background-modifier-border); }
.nimble-add-monster-modal .nimble-add-filter { height: 1.7rem; padding: 0 0.65rem; border-radius: 999px; font-size: 0.78rem; box-shadow: none; background: var(--background-secondary); border: 1px solid var(--background-modifier-border); color: var(--text-muted); }
.nimble-add-monster-modal .nimble-add-filter:hover { color: var(--text-normal); }
.nimble-add-monster-modal .nimble-add-filter.is-active { background: var(--interactive-accent); border-color: var(--interactive-accent); color: var(--text-on-accent); }
.nimble-add-monster-modal .nimble-add-row { display: flex; align-items: center; gap: 0.65rem; transition: background 0.2s; }
.nimble-add-monster-modal .nimble-add-row.is-added { background: color-mix(in srgb, var(--nimble-ok) 14%, transparent); }
.nimble-add-monster-modal .nimble-add-level {
	flex-shrink: 0; min-width: 2.1rem; height: 1.6rem; padding: 0 0.35rem; border-radius: 6px;
	display: inline-flex; align-items: center; justify-content: center;
	font-size: 0.78rem; font-weight: 700; font-variant-numeric: tabular-nums;
	background: color-mix(in srgb, var(--nimble-hp) 14%, transparent); color: var(--nimble-hp);
}
.nimble-add-monster-modal .nimble-add-level.role-minion { background: color-mix(in srgb, var(--nimble-minion) 16%, transparent); color: var(--nimble-minion); }
.nimble-add-monster-modal .nimble-add-level.role-legendary { background: color-mix(in srgb, var(--nimble-legendary) 18%, transparent); color: var(--nimble-legendary); }
.nimble-add-monster-modal .nimble-add-text { flex: 1; min-width: 0; }
.nimble-add-monster-modal .nimble-add-name { display: flex; align-items: baseline; gap: 0.45rem; font-weight: 600; }
.nimble-add-monster-modal .nimble-add-here:not(:empty) { font-size: 0.7rem; font-weight: 600; padding: 0 0.4rem; border-radius: 999px; background: color-mix(in srgb, var(--nimble-ok) 18%, transparent); color: color-mix(in srgb, var(--nimble-ok) 80%, var(--text-normal)); }
.nimble-add-monster-modal .nimble-add-meta { font-size: 0.78rem; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-add-monster-modal .nimble-add-qty { display: inline-flex; align-items: center; flex-shrink: 0; border: 1px solid var(--background-modifier-border); border-radius: 8px; background: var(--background-primary); height: 1.9rem; }
.nimble-add-monster-modal .nimble-add-step { width: 1.8rem; height: 100%; padding: 0; border: none; box-shadow: none; background: transparent; color: var(--text-muted); display: inline-flex; align-items: center; justify-content: center; }
.nimble-add-monster-modal .nimble-add-step:hover { color: var(--text-normal); background: var(--background-modifier-hover); }
.nimble-add-monster-modal .nimble-add-step svg { width: 13px; height: 13px; }
.nimble-add-monster-modal .nimble-add-n { min-width: 1.4rem; text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
.nimble-add-monster-modal .nimble-add-btn { flex-shrink: 0; display: inline-flex; align-items: center; gap: 0.25rem; height: 1.9rem; padding: 0 0.7rem; min-width: 4.6rem; justify-content: center; }
.nimble-add-monster-modal .nimble-add-btn svg { width: 13px; height: 13px; }

/* Add several (count-modal.ts): labelled rows (what / control), then a summary beside the actions. */
/* Add several (nimble/count-modal.ts): a compact game dialog. The count on the keypad's keys (the number takes
   typing), Strength as three equal segments with what you'd get beside its label, the total above the footer. */
.nimble-count-modal .nimble-count-to { margin-top: -8px; font: 500 13px/18px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text-2, var(--text-muted)); }
.nimble-count-modal .nimble-count-row { display: grid; gap: 8px; }
.nimble-count-modal .nimble-count-desc { font-variant-numeric: tabular-nums; }
.nimble-count-modal .nimble-count-stepper { display: grid; grid-template-columns: 44px minmax(0, 1fr) 44px; gap: 6px; }
.nimble-count-modal .nimble-count-stepper > button.nimble-count-step { width: 44px; height: 44px; }
.nimble-count-modal input.nimble-count-input { width: 100%; height: 44px; padding: 0; border: 0; border-radius: var(--ev-r-md, 6px); background: var(--ev-surface-2, var(--background-secondary)); box-shadow: inset 0 0 0 1px var(--ev-line, transparent); text-align: center; color: var(--ev-text, var(--text-normal)); font: 700 24px/1 var(--ev-font-num, var(--font-interface)); font-variant-numeric: tabular-nums lining-nums; -moz-appearance: textfield; appearance: textfield; }
.nimble-count-modal input.nimble-count-input:focus { box-shadow: inset 0 0 0 2px var(--ev-text, var(--interactive-accent)); }
.nimble-count-input::-webkit-inner-spin-button, .nimble-count-input::-webkit-outer-spin-button { margin: 0; -webkit-appearance: none; appearance: none; }
.nimble-count-modal .nimble-count-shift button.nimble-count-seg { justify-content: center; height: 36px; font-size: 14px; }
.nimble-count-modal .nimble-count-summary { font: 600 13px/18px var(--ev-font-ui, var(--font-interface)); color: var(--ev-text-2, var(--text-muted)); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
/* Desktop: row controls show on hover or when the row is selected, so the list stays calm */
@media (hover: hover) and (pointer: fine) {
	.nimble-add-monster-modal .nimble-add-row :is(.nimble-add-qty, .nimble-add-btn) { opacity: 0; transition: opacity 0.12s; }
	.nimble-add-monster-modal .nimble-add-row:is(:hover, .is-selected, .is-added) :is(.nimble-add-qty, .nimble-add-btn) { opacity: 1; }
}
body.is-phone .nimble-add-monster-modal .nimble-add-meta { white-space: normal; }
body.is-phone .nimble-add-monster-modal .nimble-add-row { flex-wrap: wrap; }
body.is-phone .nimble-add-monster-modal .nimble-add-text { flex-basis: calc(100% - 3rem); }
body.is-phone .nimble-add-monster-modal .nimble-add-qty { margin-left: 2.75rem; height: 2.4rem; }
body.is-phone .nimble-add-monster-modal .nimble-add-step { width: 2.4rem; }
body.is-phone .nimble-add-monster-modal .nimble-add-btn { flex: 1; height: 2.4rem; }

/* Bestiary: filter toggle and the narrow (phone / slim pane) layout */
.nimble-bestiary .bestiary-search { display: flex; align-items: center; gap: 0.3rem; }
.nimble-bestiary .bestiary-filter-toggle { display: none; position: relative; flex-shrink: 0; }
.nimble-bestiary .bestiary-filter-toggle.has-active::after { content: ""; position: absolute; top: 5px; right: 5px; width: 7px; height: 7px; border-radius: 50%; background: var(--interactive-accent); }
/* (Each rule names :not(#nimble-pill) to stay above the shared pill rule: the Back button is a pill.) */
.nimble-bestiary .bestiary-back:not(#nimble-pill) { display: none; }
.nimble-bestiary .bestiary-layout.is-narrow { grid-template-columns: minmax(0, 1fr); }
.nimble-bestiary .bestiary-side, .nimble-bestiary .bestiary-detail { min-width: 0; }
.nimble-bestiary .is-narrow .bestiary-level-input { width: 4.5rem; flex: none; }
body.is-phone .nimble-bestiary .bestiary-side, body.is-phone .nimble-bestiary .bestiary-detail { padding-bottom: 5.5rem; }
.nimble-bestiary .is-narrow .bestiary-side { border-right: none; min-height: 0; height: 100%; }
.nimble-bestiary .is-narrow .bestiary-filter-toggle { display: inline-flex; }
.nimble-bestiary .is-narrow:not(.filters-open) .bestiary-filters { display: none; }
.nimble-bestiary .is-narrow .bestiary-detail { display: none; padding: 0.5rem 0.75rem 2rem; }
.nimble-bestiary .is-narrow.show-detail .bestiary-side { display: none; }
.nimble-bestiary .is-narrow.show-detail .bestiary-detail { display: block; height: 100%; }
.nimble-bestiary .is-narrow .bestiary-back:not(#nimble-pill) {
	display: inline-flex; align-items: center; gap: 0.2rem;
	position: sticky; top: 0; z-index: 2;
	margin: 0 0 0.4rem -0.3rem; padding: 0 0.6rem 0 0.3rem; height: 2.2rem;
	background: var(--background-primary); box-shadow: none; color: var(--text-accent);
}
.nimble-bestiary .is-narrow .bestiary-back svg { width: 18px; height: 18px; }
.nimble-bestiary .is-narrow .bestiary-row-add { opacity: 1; }
.nimble-bestiary .is-narrow .bestiary-filter-row { flex-wrap: wrap; }
.nimble-bestiary .is-narrow .bestiary-filter-label { width: 100%; }

/* Party editor: cards when narrow. Labels only show on cards. */
.nimble-party-table { container-type: inline-size; }
.nimble-party-field { display: flex; flex-direction: column; min-width: 0; }
.nimble-party-field-label { display: none; }
@container (max-width: 560px) {
	.nimble-party-head { display: none; }
	.nimble-party-row {
		grid-template-columns: repeat(4, minmax(0, 1fr)) 2.4rem;
		gap: 0.45rem 0.4rem;
		padding: 0.55rem;
		border: 1px solid var(--background-modifier-border);
		border-radius: var(--nimble-radius, 8px);
	}
	.nimble-party-field { display: flex; flex-direction: column; gap: 0.15rem; min-width: 0; }
	.nimble-party-field-label { display: block; font-size: 0.68rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-muted); }
	.nimble-party-field.field-name { grid-column: 1 / 3; }
	.nimble-party-field.field-class { grid-column: 3 / 5; }
	.nimble-party-del { grid-column: 5; grid-row: 1; align-self: end; }
}

/* Builder: stack the columns on narrow screens */
@media (max-width: 640px) {
	.nimble-builder-modal .builder-cols { grid-template-columns: 1fr; }
	.nimble-builder-modal .builder-col:last-child { order: -1; }
	.nimble-builder-modal .builder-results { height: auto; max-height: 42vh; }
	.nimble-builder-modal .builder-picked { height: auto; min-height: 3rem; max-height: 30vh; }
	.nimble-builder-modal .nimble-meter-label { font-size: 0.6rem; }
	.nimble-builder-modal .nimble-meter-tick:nth-of-type(odd) .nimble-meter-label { top: -16px; }
	.nimble-builder-modal .nimble-meter { margin-top: 1.3rem; }
	.nimble-builder-modal .builder-name { min-width: 0; }
}

/* Maps on phones: a shorter viewport and the token tray underneath */
body.is-phone .nimble-map-viewport { flex: none; height: 60vh; resize: none; }
body.is-phone .nimble-map-body, body.is-phone .nimble-map-main { flex-direction: column; }
body.is-phone .nimble-map-tray { width: auto; max-height: none; border-left: none; border-top: 1px solid var(--background-modifier-border); flex-direction: row; flex-wrap: wrap; }
/* The same stacking in a narrow pane on any device (sidebar, split, hover preview, Canvas card).
   .nimble-map is the container, so only elements inside it are restyled here. */
.nimble-map { container-type: inline-size; }
@container (max-width: 520px) {
	.nimble-map-viewport { flex: none; }
	.nimble-map-body { flex-direction: column; }
	.nimble-map-tray { width: auto; max-height: none; border-left: none; border-top: 1px solid var(--background-modifier-border); flex-direction: row; flex-wrap: wrap; }
}

/* Finger-sized targets wherever the main pointer is a finger */
@media (pointer: coarse) {
	.nimble-map-viewport { resize: none; }

	/* Encounter chips and bestiary: no hover, so show the controls */
	.nimble-bestiary .bestiary-row-add { opacity: 1; }
	.nimble-bestiary .bestiary-row { padding: 0.5rem 0.4rem; }
	.nimble-segmented button { padding: 0.4rem 0.7rem; font-size: 0.85rem; }
	.nimble-statblock .statblock-action { padding: 0.45rem 0.8rem; font-size: 0.88rem; }
	.nimble-inline-ref .nimble-inline-add-btn { min-width: 1.6em; }

	/* Tracker: finger-sized marks, HP and chips */
	.ev-tracker .ev-mark { width: 26px; height: 26px; }
	.ev-tracker .ev-card-btn, .ev-tracker .ev-card-icon { height: 42px; }
	.ev-tracker .ev-card-icon { width: 42px; }
	.ev-tracker .ev-foot > button { height: 44px; }
	.ev-tracker .ev-foot-back { width: 44px; }
	.nimble-encounter-tracker .phase-pill { height: 44px; }
	.nimble-encounter-tracker .condition-tag { height: 30px; }
	.nimble-encounter-tracker .remove-condition { width: 26px; height: 26px; }
	.nimble-encounter-tracker .wound-pip { width: 18px; height: 18px; }
	.nimble-encounter-tracker .wound-pip.is-skull, .nimble-encounter-tracker .wound-pip.is-skull svg { width: 20px; height: 20px; }
	.nimble-encounter-tracker .nimble-acts.is-lg > * { width: 26px; height: 34px; }
	.nimble-encounter-tracker .nimble-minions.is-lg > * { width: 22px; height: 22px; }
	.nimble-encounter-tracker .group-attack, .nimble-encounter-tracker .laststand-btn { height: 40px; }

	/* Map */
	.nimble-map-toolbar button { min-height: 2.3rem; }

	/* Builder and party */
	.nimble-builder-modal .builder-result { padding-top: 0.5rem; padding-bottom: 0.5rem; }
	.nimble-builder-modal .builder-pick .clickable-icon { width: 2.3rem; height: 2.3rem; }
	.nimble-party-row input { min-height: 2.4rem; font-size: 16px; }
}

/* iOS zooms into inputs under 16px; keep typing fields at 16px on phones */
body.is-phone .nimble-encounter-tracker input, body.is-phone .nimble-bestiary input, body.is-phone .nimble-builder-modal input, body.is-phone .nimble-builder-modal textarea { font-size: 16px; }

/* Obsidian's tablet theme pads every button (.is-tablet button:not(.clickable-icon)),
   which outranks the compact controls above. Put their padding back. */
body.is-tablet :is(.turn-toggle, .pip, .creature-label, .stepper-btn, .nimble-inline-add-btn, .link-btn, .hp-pad-keys button, .ev-mark, .ev-card-icon, .ev-foot-back, .wound-pip, .minion-pip, .action-pip, .hp-display, .hp-pad-close) { padding: 0; }
body.is-tablet :is(.round-btn, .phase-pill, .group-attack, .laststand-btn, .hp-btn, .phase-chip, .nimble-map-btn, .statblock-action, .bestiary-back, .nimble-difficulty.is-button) { padding-left: 0.6rem; padding-right: 0.6rem; }
body.is-tablet .nimble-encounter-tracker .remove-condition { padding: 0; }
body.is-tablet :is(.ev-card-btn, .ev-foot-primary, .ev-foot-second, .hp-pad-qa, .hp-pad-choice, .hp-pad-mode, .hp-pad-cancel, .hp-pad-apply) { padding-left: 10px; padding-right: 10px; }
body.is-tablet .nimble-segmented button { padding: 0.4rem 0.7rem; }
body.is-tablet .condition-picker .condition-option { padding: 0.25rem 0.5rem; }
body.is-mobile .nimble-bestiary .bestiary-level-input { width: 4.5rem; flex: none; }

/* ============================================
   CAMPAIGNS: the Campaign panel and the ```nimble-campaign dashboard
   ============================================ */

.nimble-campaign-view { padding: 0.6rem 0.6rem 2rem; font-size: 0.9rem; }
.nimble-campaign-view .campaign-switcher { display: flex; align-items: center; gap: 0.3rem; margin-bottom: 0.5rem; }
.nimble-campaign-view .campaign-switch-btn {
	flex: 1; min-width: 0; display: flex; align-items: center; gap: 0.45rem; justify-content: flex-start;
	height: auto; padding: 0.45rem 0.55rem; border-radius: 8px; box-shadow: none;
	background: var(--background-secondary); border: 1px solid var(--background-modifier-border);
	font-weight: 700; font-size: 0.95rem; text-align: left;
}
.nimble-campaign-view .campaign-switch-btn:hover { border-color: var(--interactive-accent); }
.nimble-campaign-view .campaign-switch-icon { display: inline-flex; color: var(--text-accent); }
.nimble-campaign-view .campaign-switch-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-campaign-view .campaign-switch-chevron { display: inline-flex; color: var(--text-faint); }
.nimble-campaign-view .campaign-switch-btn svg, .nimble-campaign-view .campaign-switcher .clickable-icon svg { width: 16px; height: 16px; }
/* Search bar under the switcher: a button that looks like a field and opens Spotlight */
.nimble-campaign-view .campaign-search {
	display: flex; align-items: center; gap: 0.45rem; justify-content: flex-start; width: 100%; min-width: 0;
	height: auto; margin-bottom: 0.5rem; padding: 0.45rem 0.55rem; border-radius: 8px; box-shadow: none;
	background: var(--background-primary); border: 1px solid var(--background-modifier-border);
	color: var(--text-muted); font-weight: 400; font-size: 0.95rem; text-align: left;
}
.nimble-campaign-view .campaign-search:hover { border-color: var(--interactive-accent); }
.nimble-campaign-view .campaign-search:focus-visible { border-color: var(--interactive-accent); outline: 2px solid var(--interactive-accent); outline-offset: 1px; }
.nimble-campaign-view .campaign-search-icon { display: inline-flex; flex: none; color: var(--text-faint); }
.nimble-campaign-view .campaign-search-icon svg { width: 16px; height: 16px; }
.nimble-campaign-view .campaign-search-placeholder { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-campaign-view .campaign-search-kbd {
	flex: none; padding: 0 0.35rem; border-radius: 4px; line-height: 1.5;
	border: 1px solid var(--background-modifier-border); background: var(--background-secondary);
	color: var(--text-faint); font-family: var(--font-interface); font-size: var(--font-ui-smaller); white-space: nowrap;
}

.campaign-party {
	display: inline-flex; align-items: center; gap: 0.4rem; height: auto; padding: 0.25rem 0.6rem;
	border-radius: 999px; box-shadow: none; background: color-mix(in srgb, var(--nimble-hero, var(--interactive-accent)) 14%, transparent);
	border: none; color: var(--text-normal); font-size: 0.8rem; font-weight: 600; max-width: 100%;
}
.campaign-party:hover { background: color-mix(in srgb, var(--nimble-hero, var(--interactive-accent)) 24%, transparent); }
.campaign-party-icon { display: inline-flex; color: var(--nimble-hero, var(--interactive-accent)); }
.campaign-party-icon svg { width: 14px; height: 14px; }
.campaign-party-hint { color: var(--text-accent); font-weight: 500; }
.campaign-party-hint::before { content: "· "; color: var(--text-faint); }

.campaign-continue {
	display: flex; align-items: center; gap: 0.45rem; width: 100%; height: auto; margin: 0.6rem 0 0.2rem;
	padding: 0.5rem 0.7rem; border-radius: 8px; justify-content: flex-start; text-align: left;
}
.campaign-continue svg { width: 15px; height: 15px; }
.campaign-continue-label { font-weight: 700; }
.campaign-continue-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; opacity: 0.9; font-weight: 500; }

.campaign-heading {
	display: flex; align-items: center; justify-content: space-between; margin: 0.9rem 0 0.2rem; padding: 0 0.2rem;
	font-size: 0.7rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted);
}
.campaign-heading .clickable-icon { padding: 2px; }
.campaign-heading svg { width: 14px; height: 14px; }

.campaign-group { margin: 0.1rem 0; }
.campaign-group-head {
	display: flex; align-items: center; gap: 0.3rem; padding: 0.3rem 0.25rem; border-radius: 6px; cursor: pointer; min-height: 1.9rem;
}
.campaign-group-head:hover { background: var(--background-modifier-hover); }
.campaign-group-head:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--interactive-accent); }
.campaign-chevron { display: inline-flex; color: var(--text-faint); transition: transform 0.12s; transform: rotate(90deg); }
.campaign-group.is-collapsed .campaign-chevron { transform: none; }
.campaign-chevron svg { width: 14px; height: 14px; }
.campaign-group-head .clickable-icon { padding: 2px; opacity: 0.55; }
.campaign-group-head:hover .clickable-icon, .campaign-group-head .clickable-icon:focus-visible { opacity: 1; }
.campaign-group-head .clickable-icon svg { width: 14px; height: 14px; }
.campaign-chapter-head.is-current .campaign-chapter-name { color: var(--text-accent); }
.campaign-chapter-title { flex: 1; min-width: 0; display: flex; flex-direction: column; line-height: 1.25; }
.campaign-chapter-label { font-size: 0.66rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-accent); }
.campaign-chapter-name { font-weight: 700; color: var(--text-normal); text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.campaign-chapter-name:hover { text-decoration: underline; }
.campaign-section-icon { display: inline-flex; color: var(--text-muted); }
.campaign-section-icon svg { width: 14px; height: 14px; }
.campaign-section-name { flex: 1; min-width: 0; font-weight: 600; }
.campaign-count { font-size: 0.7rem; color: var(--text-faint); font-variant-numeric: tabular-nums; padding: 0 0.2rem; }

.campaign-group-body { padding-left: 0.95rem; margin-left: 0.4rem; border-left: 1px solid var(--background-modifier-border); }
.campaign-note {
	display: flex; align-items: center; gap: 0.4rem; padding: 0.22rem 0.4rem; border-radius: 5px;
	color: var(--text-normal); text-decoration: none; min-height: 1.75rem;
}
.campaign-note:hover { background: var(--background-modifier-hover); color: var(--text-normal); }
.campaign-note.is-current { background: color-mix(in srgb, var(--interactive-accent) 16%, transparent); font-weight: 600; }
.campaign-note-icon { display: inline-flex; color: var(--text-faint); flex-shrink: 0; }
.campaign-note-icon svg { width: 14px; height: 14px; }
.campaign-note.kind-quest .campaign-note-icon { color: var(--color-orange); }
.campaign-note.kind-map .campaign-note-icon, .campaign-note.is-current .campaign-note-icon { color: var(--text-accent); }
.campaign-note-area {
	flex-shrink: 0; min-width: 2rem; text-align: center; font-size: 0.68rem; font-weight: 700; font-variant-numeric: tabular-nums;
	padding: 0 0.25rem; border-radius: 4px; background: var(--background-modifier-hover); color: var(--text-muted);
}
.campaign-note-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.campaign-note.is-quest-done, .campaign-note.is-quest-failed { color: var(--text-faint); }
.campaign-note.is-quest-done .campaign-note-icon { color: var(--color-green); }
.campaign-note.is-quest-failed .campaign-note-title { text-decoration: line-through; }
.campaign-note.is-quest-failed .campaign-note-icon { color: var(--text-faint); }
.campaign-loose .campaign-note { padding-left: 0.3rem; }
.campaign-empty { font-size: 0.8rem; color: var(--text-muted); padding: 0.3rem 0.4rem; }
.campaign-add-inline { display: inline-block; font-size: 0.8rem; padding: 0.25rem 0.4rem; }

.campaign-heading > span:first-child { flex: 1; }
.campaign-file .campaign-note-title { color: var(--text-muted); }
.campaign-empty .campaign-add-inline { padding: 0; }

/* Open quests, each with a status dot: filled when active, a ring when it's waiting to be taken up. */
.campaign-heading-note { font-weight: 600; text-transform: none; letter-spacing: 0; }
.campaign-quests { display: grid; gap: 1px; }
.campaign-quest {
	display: flex; align-items: center; gap: 8px; min-height: 1.75rem; padding: 0.22rem 0.5rem; border-radius: 6px;
	color: var(--text-normal); text-decoration: none;
}
.campaign-quest:hover { background: var(--background-modifier-hover); color: var(--text-normal); }
.campaign-quest-dot { flex: none; width: 8px; height: 8px; margin: 0 3px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ev-accent-text, var(--text-accent)); }
.campaign-quest-dot.is-active { background: var(--ev-accent-text, var(--text-accent)); }
.campaign-quest-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (pointer: coarse) { .campaign-quest { min-height: 2.6rem; padding: 0.4rem 0.5rem; } }

/* The panel (and the home note's dashboard) in the active campaign's game look (design study: #nimble/campaign,
   #5e/campaign): the game's paper, the campaign's name in its type, Continue in its accent, rows on its tokens. */
.nimble-campaign-view[class*="ev-sys-"] { background: var(--ev-bg); font-family: var(--ev-font-ui); }
.nimble-campaign-block[class*="ev-sys-"] { background: var(--ev-bg); border-color: var(--ev-line); font-family: var(--ev-font-ui); }
[class*="ev-sys-"]:is(.nimble-campaign-view, .nimble-campaign-block) { color: var(--ev-text); }
.nimble-campaign-view[class*="ev-sys-"] :is(.campaign-switch-btn, .campaign-search) { border: none; border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line); }
.nimble-campaign-view[class*="ev-sys-"] :is(.campaign-switch-btn, .campaign-search):hover { box-shadow: inset 0 0 0 1px var(--ev-line-strong); }
.nimble-campaign-view[class*="ev-sys-"] .campaign-switch-btn { padding: 9px 10px; }
.nimble-campaign-view[class*="ev-sys-"] .campaign-switch-icon { color: var(--ev-accent-text); }
.nimble-campaign-view[class*="ev-sys-"] .campaign-switch-name { font: var(--ev-display-weight) 15px/normal var(--ev-font-display); font-variant: var(--ev-display-variant); color: var(--ev-text); }
.nimble-campaign-view.ev-sys-nimble .campaign-switch-name { font: italic 900 16px/normal var(--ev-font-name); font-variant: normal; position: relative; top: 1px; } /* Vollkorn's capitals sit 1.4px high in its box (measured) */
.nimble-campaign-view.ev-sys-dnd5e .campaign-switch-name { font: 700 17px/normal var(--ev-font-display); font-variant: small-caps; color: var(--x5-sb14-name); }
.nimble-campaign-view[class*="ev-sys-"] .campaign-search { padding: 7px 10px; color: var(--ev-text-2); }
/* The GM / Player tag: dark, white text. */
[class*="ev-sys-"] .campaign-role-pill, [class*="ev-sys-"] .campaign-role-pill.role-player { padding: 3px 6px; border-radius: 4px; background: var(--ev-accent); color: var(--ev-on-accent); font: 700 10.5px/1 var(--ev-font-ui); letter-spacing: 0.04em; }
[class*="ev-sys-"] .campaign-continue { margin: 10px 0 2px; padding: 9px 12px; gap: 6px; border-radius: var(--ev-r-md); font: 600 13.5px/18px var(--ev-font-ui); }
[class*="ev-sys-"] .campaign-continue-icon { display: inline-flex; }
[class*="ev-sys-"] .campaign-continue-label { font-weight: 500; opacity: 0.85; }
[class*="ev-sys-"] .campaign-continue-name { font-weight: 700; opacity: 1; }
[class*="ev-sys-"] .campaign-heading { margin: 14px 4px 2px; padding: 0; font: 700 11px/14px var(--ev-font-ui); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
[class*="ev-sys-"] .campaign-heading-note { font: 600 11px/14px var(--ev-font-ui); }
[class*="ev-sys-"] :is(.campaign-note, .campaign-quest, .campaign-group-head) { border-radius: 6px; }
[class*="ev-sys-"] :is(.campaign-note, .campaign-quest):hover, [class*="ev-sys-"] .campaign-group-head:hover { background: color-mix(in srgb, var(--ev-text) 6%, transparent); }
[class*="ev-sys-"] :is(.campaign-note, .campaign-quest).is-current { background: var(--ev-now); box-shadow: inset 0 0 0 1px var(--ev-now-line); font-weight: 500; }
[class*="ev-sys-"] :is(.campaign-note-icon, .campaign-section-icon, .campaign-chevron, .campaign-count) { color: var(--ev-text-2); }
[class*="ev-sys-"] .campaign-note.is-current .campaign-note-icon, [class*="ev-sys-"] .campaign-note.kind-quest .campaign-note-icon { color: var(--ev-accent-text); }
[class*="ev-sys-"] .campaign-note.is-quest-done .campaign-note-icon { color: var(--ev-ok); }
[class*="ev-sys-"] .campaign-chapter-label { color: var(--ev-accent-text); }
[class*="ev-sys-"] .campaign-chapter-name { color: var(--ev-text); }
[class*="ev-sys-"] .campaign-group-body { border-left-color: var(--ev-line); }
[class*="ev-sys-"] .campaign-note-area { background: var(--ev-chip-bg); color: var(--ev-chip-text); }

/* Drag and drop: the row being dragged, and the chapter or folder it would land in */
.campaign-note.is-dragging { opacity: 0.45; }
.campaign-group.is-drop-target > .campaign-group-head,
.campaign-heading.is-drop-target {
	background: color-mix(in srgb, var(--interactive-accent) 18%, transparent);
	box-shadow: inset 0 0 0 1px var(--interactive-accent); border-radius: 5px;
}
.campaign-group.is-drop-target > .campaign-group-body { border-left-color: var(--interactive-accent); }

/* Campaign notes: the cards at the top of quests, locations and sessions (core/campaign-cards.ts; design study:
   #nimble/campaign, #5e/campaign). One anatomy in every game; the game's tokens give colour, paper and type, and
   each game adds what its books add (5e's read-aloud box, Nimble's monsters). Sections a card shows are left out
   of the note's reading view (.ev-on-card), so nothing shows twice. */
.markdown-preview-view.ev-cq-host > .markdown-preview-sizer > .ev-on-card { display: none; }
/* The card carries the title: the reading view's inline title steps aside (editing keeps it, to rename the note). */
.markdown-preview-view.ev-cq-host .inline-title { display: none; }
.nimble-note-card:is(.kind-quest, .kind-location, .kind-session) { margin: 0.25rem 0 1.2rem; }
.ev-cq {
	position: relative; display: grid; gap: 10px; padding: 18px 20px;
	border-radius: var(--ev-r-lg, 12px); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line);
	color: var(--ev-text); font: 500 14.5px/20px var(--ev-font-ui); container-type: inline-size;
}
.ev-cq p { margin: 0; }
.ev-cq-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; align-items: start; }
.ev-cq-kicker { grid-column: 1; display: flex; align-items: center; gap: 6px; min-width: 0; font: 700 11.5px/16px var(--ev-font-ui); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ev-accent-text); }
.ev-cq-kicker-icon { display: inline-flex; flex: none; }
.ev-cq-kicker-icon svg { width: 13px; height: 13px; }
.ev-cq-title { grid-column: 1; margin: 0; font: 700 30px/1.15 var(--ev-font-name, var(--ev-font-display)); color: var(--ev-text); text-wrap: balance; overflow-wrap: anywhere; }
.ev-cq-stamp { grid-column: 2; grid-row: 1 / span 2; align-self: center; padding: 5px 12px; border-radius: 999px; background: var(--ev-accent); color: var(--ev-on-accent); font: 700 12px/16px var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.ev-cq-stamp.is-open { background: var(--ev-surface-2); color: var(--ev-text); box-shadow: inset 0 0 0 1px var(--ev-line-strong); }
.ev-cq-stamp.is-done { background: var(--ev-text-2); color: var(--ev-surface); }
.ev-cq-stamp.is-failed { background: var(--ev-danger-text); color: #FFFFFF; }
/* Facts: icon, small label, value; each label stays with its value as the row wraps. */
.ev-cq-facts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 22px; }
.ev-cq-fact { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
.ev-cq-fact-icon { display: inline-flex; flex: none; color: var(--ev-text-2); }
.ev-cq-fact-icon svg { width: 14px; height: 14px; }
.ev-cq-fact-label { flex: none; font: 700 11px/14px var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-cq-fact-value { min-width: 0; font: 600 14.5px/20px var(--ev-font-ui); }
.ev-cq a.internal-link { color: var(--ev-accent-text); }
.ev-cq a.internal-link.is-unresolved { color: var(--ev-accent-text); opacity: 0.75; }
/* People: a portrait (or initials) and the name. */
.ev-cq-who { display: inline-flex; align-items: center; gap: 6px; min-width: 0; font: 600 14.5px/20px var(--ev-font-ui); }
.ev-cq-avatar { flex: none; width: 24px; height: 24px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ev-now-line); }
.ev-cq-avatar.is-initials { display: inline-flex; align-items: center; justify-content: center; background: radial-gradient(120% 120% at 30% 20%, var(--ev-surface) 0%, var(--ev-surface-2) 70%); color: var(--ev-accent-text); font: var(--ev-display-weight) 9.5px/1 var(--ev-font-display); font-variant: var(--ev-display-variant); letter-spacing: 0.02em; }
.ev-cq-whos .ev-cq-avatar { width: 26px; height: 26px; }
.ev-cq-whos { display: flex; flex-wrap: wrap; gap: 8px 16px; }
/* Section heads inside a card; the game styles them (Nimble's khaki ribbon, 5e's red small caps over gold). */
.ev-cq-sec { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-top: 6px; padding-bottom: 5px; border-bottom: 1px solid var(--ev-line); font: 700 12px/16px var(--ev-font-ui); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-cq-sec-note { font-weight: 600; text-transform: none; letter-spacing: 0; }
/* Objectives: tick them here, and they're ticked in the note. */
.ev-cq ul.ev-cq-objs { display: grid; gap: 7px; margin: 0; padding: 0; list-style: none; }
.ev-cq ul.ev-cq-objs > li::marker { content: none; }
.ev-cq ul.ev-cq-objs > li { margin: 0; padding: 0; display: flex; align-items: flex-start; gap: 10px; font: 500 15px/21px var(--ev-font-ui); }
button.ev-cq-box { flex: none; display: grid; place-items: center; width: 18px; height: 18px; margin-top: 1.5px; padding: 0; border: none; border-radius: 4px; background: var(--ev-surface); box-shadow: inset 0 0 0 1.5px var(--ev-line-strong); color: var(--ev-on-accent); cursor: pointer; }
button.ev-cq-box svg { width: 12px; height: 12px; }
.ev-cq ul.ev-cq-objs > li.is-done button.ev-cq-box { background: var(--ev-accent); box-shadow: none; }
.ev-cq ul.ev-cq-objs > li.is-done .ev-cq-obj-text { color: var(--ev-text-2); text-decoration: line-through; }
body.is-tablet button.ev-cq-box { padding: 0; }
.ev-cq-secret { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; padding: 10px 12px; border-radius: var(--ev-r-md, 8px); background: var(--ev-surface-2); box-shadow: inset 0 0 0 1px var(--ev-line); font: 500 14px/20px var(--ev-font-ui); }
.ev-cq-secret-label { display: inline-flex; align-items: center; gap: 5px; font: 700 11.5px/20px var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-cq-secret-icon { display: inline-flex; }
.ev-cq-secret-icon svg { width: 13px; height: 13px; }
.ev-cq-secret-text { display: grid; gap: 6px; }
/* A place: its banner (its image, or contour lines in the game's tint) and emblem; who's here; where it leads. */
.ev-cq-banner { position: relative; height: 92px; margin: -18px -20px 4px; overflow: hidden; border-radius: var(--ev-r-lg, 12px) var(--ev-r-lg, 12px) 0 0; background: color-mix(in srgb, var(--ev-accent) 9%, var(--ev-surface-2)); color: color-mix(in srgb, var(--ev-accent) 34%, transparent); }
.ev-cq-banner.has-image { height: 140px; }
.ev-cq-banner-img { display: block; width: 100%; height: 100%; object-fit: cover; }
.ev-cq-contours { position: absolute; inset: 0; width: 100%; height: 100%; }
.ev-cq-emblem { position: absolute; left: 20px; bottom: 12px; display: grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; background: var(--ev-surface); color: var(--ev-accent-text); box-shadow: inset 0 0 0 1.5px var(--ev-line-strong), 0 2px 6px rgb(0 0 0 / 0.08); }
.ev-cq-emblem svg { width: 22px; height: 22px; }
.ev-cq-leads { display: flex; flex-wrap: wrap; gap: 6px 16px; font: 600 14.5px/20px var(--ev-font-ui); }
/* What a game adds: 5e's read-aloud, Nimble's monsters. */
.ev-cq-read { display: grid; gap: 4px; padding: 12px 16px; border-radius: 4px; background: color-mix(in srgb, var(--ev-gold, var(--ev-accent)) 14%, var(--ev-surface)); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ev-gold, var(--ev-accent)) 45%, transparent), 0 1px 2px rgb(88 24 13 / 0.08); }
.ev-cq-read-label { display: inline-flex; align-items: center; gap: 5px; font: 700 11px/14px var(--ev-font-ui); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-cq-read-icon { display: inline-flex; }
.ev-cq-read-icon svg { width: 13px; height: 13px; }
.ev-cq-read-text { margin: 0; font: italic 400 17px/1.5 var(--ev-font-display); }
.ev-cq .nimble-note-stats { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.ev-cq ul.ev-cq-recap > li { margin: 0; }
.ev-cq-mons { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }
.ev-cq-mons-label { margin-right: 4px; font: 700 11px/14px var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ev-text-2); }
/* A session: who was at the table, what happened, quests moved (tags), the loot, next time. */
.ev-cq-at { display: grid; gap: 6px; }
.ev-cq-at-label { font: 700 11px/14px var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; color: var(--ev-text-2); }
.ev-cq ul.ev-cq-recap { display: grid; gap: 4px; margin: 0; padding-left: 20px; font: 500 15px/21px var(--ev-font-ui); }
.ev-cq-threads { display: grid; gap: 6px; }
.ev-cq-thread { display: flex; align-items: center; justify-content: space-between; gap: 12px; font: 600 14.5px/20px var(--ev-font-ui); }
.ev-cq-thread-name { min-width: 0; }
.ev-cq-change { flex: none; padding: 3px 9px; border-radius: 999px; background: var(--ev-accent); color: var(--ev-on-accent); font: 700 11.5px/16px var(--ev-font-ui); letter-spacing: 0.05em; text-transform: uppercase; }
.ev-cq-change.is-new { background: var(--ev-text); color: var(--ev-surface); }
.ev-cq-change.is-done { background: var(--ev-text-2); color: var(--ev-surface); }
.ev-cq-change.is-failed { background: var(--ev-danger-text); color: #FFFFFF; }
.ev-cq-loot { display: flex; flex-wrap: wrap; gap: 6px; }
.ev-cq-loot-item { padding: 4px 10px; border-radius: 999px; background: var(--ev-chip-bg); color: var(--ev-chip-text); font: 600 13px/18px var(--ev-font-ui); }
.ev-cq-next { display: flex; flex-wrap: wrap; gap: 4px 10px; padding: 10px 12px; border-radius: var(--ev-r-md, 8px); background: var(--ev-now); box-shadow: inset 0 0 0 1px var(--ev-now-line); font: 500 14.5px/20px var(--ev-font-ui); }
.ev-cq-next-label { font-weight: 700; color: var(--ev-accent-text); }
@container (max-width: 460px) {
	.ev-cq-title { font-size: 25px; }
	.ev-cq-head { grid-template-columns: minmax(0, 1fr); }
	.ev-cq-stamp { grid-column: 1; grid-row: auto; justify-self: start; margin-top: 6px; }
	.ev-cq-banner { height: 78px; }
	.ev-cq-thread { flex-wrap: wrap; }
}
@container (max-width: 360px) {
	.ev-cq-secret { grid-template-columns: minmax(0, 1fr); gap: 2px; }
}

/* Nimble: the sheet's charcoal frame, Vollkorn, khaki ribbons for headings, charcoal stamps. */
.ev-sys-nimble .ev-cq { border-radius: 4px; box-shadow: inset 0 0 0 2px var(--ev-bar); }
.ev-sys-nimble .ev-cq-title { font: italic 900 30px/1.12 var(--ev-font-name); }
.ev-sys-nimble .ev-cq-sec { padding: 5px 10px 4px; border: 0; border-radius: 2px; background: var(--ev-band); color: var(--ev-band-text); font: italic 900 15px/19px var(--ev-font-name); text-transform: none; letter-spacing: 0; }
.ev-sys-nimble .ev-cq-sec-note { font: 600 12.5px/19px var(--ev-font-ui); }
.ev-sys-nimble .ev-cq-stamp { border-radius: 2px; background: var(--ev-bar); color: var(--ev-on-bar); }
.ev-sys-nimble .ev-cq-stamp.is-open { background: var(--ev-surface); color: var(--ev-text); box-shadow: inset 0 0 0 2px var(--ev-bar); }
.ev-sys-nimble .ev-cq-stamp.is-done { background: var(--ev-text-2); color: #FFFFFF; }
.ev-sys-nimble .ev-cq-stamp.is-failed { background: var(--ev-danger-text); color: #FFFFFF; }
.ev-sys-nimble .ev-cq-banner { border-radius: 4px 4px 0 0; background: var(--ev-band); color: rgb(75 71 67 / 0.3); box-shadow: inset 0 0 0 2px var(--ev-bar); }
.ev-sys-nimble .ev-cq-emblem { box-shadow: inset 0 0 0 2px var(--ev-bar); color: var(--ev-text); }
.ev-sys-nimble button.ev-cq-box { border-radius: 2px; box-shadow: inset 0 0 0 2px var(--ev-bar); }
.ev-sys-nimble .ev-cq ul.ev-cq-objs > li.is-done button.ev-cq-box { background: var(--ev-bar); color: var(--ev-on-bar); }
.ev-sys-nimble .ev-cq-change { border-radius: 2px; background: var(--ev-bar); color: var(--ev-on-bar); }
.ev-sys-nimble .ev-cq-change.is-done { background: var(--ev-text-2); color: #FFFFFF; }
.ev-sys-nimble .ev-cq-change.is-failed { background: var(--ev-danger-text); color: #FFFFFF; }
.theme-dark .ev-sys-nimble .ev-cq-banner { color: rgb(233 227 215 / 0.25); }

/* 5e: the book's red and gold, Garamond small caps, a tapered red rule under the title, a boxed read-aloud. */
.ev-sys-dnd5e .ev-cq-title { font: 700 32px/1.1 var(--ev-font-display); font-variant: small-caps; letter-spacing: 0.01em; color: var(--x5-sb14-name); }
.ev-sys-dnd5e .ev-cq-head { padding-bottom: 10px; background: linear-gradient(90deg, var(--x5-sb14-rule), color-mix(in srgb, var(--x5-sb14-rule) 0%, transparent)) bottom left / 100% 3px no-repeat; }
.ev-sys-dnd5e .ev-cq-sec { border-bottom: 1.5px solid var(--x5-gold-soft); font: 700 16px/20px var(--ev-font-display); font-variant: small-caps; text-transform: none; letter-spacing: 0.02em; color: var(--x5-sb14-name); }
.ev-sys-dnd5e .ev-cq-stamp { background: transparent; color: var(--x5-sb14-rule); box-shadow: inset 0 0 0 1.5px var(--x5-sb14-rule); font: 700 15px/18px var(--ev-font-display); font-variant: small-caps; text-transform: none; letter-spacing: 0.04em; }
.ev-sys-dnd5e .ev-cq-stamp.is-done { color: var(--ev-text-2); box-shadow: inset 0 0 0 1.5px var(--ev-line-strong); }
.ev-sys-dnd5e .ev-cq-read { background: #F1E6CF; box-shadow: inset 0 0 0 1px #D5BE95, 0 1px 2px rgb(88 24 13 / 0.08); }
.theme-dark .ev-sys-dnd5e .ev-cq-read { background: #2C2218; box-shadow: inset 0 0 0 1px #5E4A2E; }
.ev-sys-dnd5e .ev-cq-banner { background: #EFE0C2; color: rgb(146 38 16 / 0.28); }
.theme-dark .ev-sys-dnd5e .ev-cq-banner { background: #2C2218; color: rgb(224 122 94 / 0.3); }
.ev-sys-dnd5e .ev-cq-emblem { box-shadow: inset 0 0 0 1.5px var(--x5-gold-soft), 0 2px 6px rgb(0 0 0 / 0.08); }
@container (max-width: 460px) {
	.ev-sys-nimble .ev-cq-title { font-size: 25px; }
	.ev-sys-dnd5e .ev-cq-title { font-size: 26px; }
}

/* New note: pick a starter, then name it */
.nimble-new-note .nimble-starter-grid {
	display: grid; grid-template-columns: repeat(auto-fill, minmax(6.2rem, 1fr)); gap: 0.4rem; margin-bottom: 0.75rem;
}
.nimble-new-note .nimble-starter {
	display: flex; flex-direction: column; align-items: center; gap: 0.3rem; height: auto; padding: 0.6rem 0.3rem;
	font-size: 0.82rem; box-shadow: none; border: 1px solid var(--background-modifier-border); background: var(--background-primary);
}
.nimble-new-note .nimble-starter:hover { border-color: var(--interactive-accent); }
.nimble-new-note .nimble-starter.is-active {
	border-color: var(--interactive-accent); color: var(--text-accent);
	background: color-mix(in srgb, var(--interactive-accent) 14%, transparent); font-weight: 600;
}
.nimble-new-note .nimble-starter-icon { display: inline-flex; }
.nimble-new-note .nimble-starter-icon svg { width: 20px; height: 20px; }
.nimble-new-note .nimble-name-input { width: 100%; margin-bottom: 0.5rem; }
.nimble-new-note .nimble-starter-map .setting-item { border: none; padding: 0.3rem 0; }
.nimble-new-note .nimble-starter-map > .setting-item-description { margin-bottom: 0.5rem; }
.nimble-new-note .nimble-starter-files { font-size: 0.82rem; }
.nimble-new-note .nimble-starter-dest { display: flex; align-items: center; gap: 0.4rem; margin: -0.1rem 0 0.6rem; }
.nimble-new-note .nimble-starter-dest-icon { display: inline-flex; flex-shrink: 0; }
.nimble-new-note .nimble-starter-dest-icon svg { width: 14px; height: 14px; }
.nimble-move-detail { display: block; color: var(--text-muted); }

.campaign-welcome { text-align: center; padding: 1.5rem 0.75rem; color: var(--text-muted); }
.campaign-welcome h4 { color: var(--text-normal); margin: 0 0 0.4rem; }
.campaign-welcome p { font-size: 0.85rem; margin: 0 0 0.9rem; }

/* The dashboard block on a campaign's home note */
.nimble-campaign-block {
	border: 1px solid var(--background-modifier-border); border-radius: var(--nimble-radius, 8px);
	padding: 0.7rem 0.85rem 0.6rem; background: var(--background-secondary); font-size: 0.92rem;
}
.nimble-campaign-block .campaign-block-head { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
.nimble-campaign-block .campaign-block-panel { display: inline-flex; align-items: center; gap: 0.35rem; margin-left: auto; height: auto; padding: 0.25rem 0.6rem; font-size: 0.8rem; box-shadow: none; }
.nimble-campaign-block .campaign-block-panel svg { width: 14px; height: 14px; }
.nimble-campaign-block .campaign-heading:first-child { margin-top: 0.6rem; }

/* Dialogs */
.nimble-name-prompt .nimble-name-input { width: 100%; margin-bottom: 0.5rem; }
.nimble-new-campaign .setting-item-control input[type="number"] { width: 5rem; }

/* Touch: roomier rows */
@media (pointer: coarse) {
	.campaign-note { min-height: 2.6rem; padding: 0.4rem 0.5rem; }
	.campaign-group-head { min-height: 2.6rem; }
	.campaign-group-head .clickable-icon { opacity: 1; padding: 6px; }
	.campaign-heading .clickable-icon { padding: 6px; }
	.campaign-party { padding: 0.45rem 0.75rem; font-size: 0.85rem; }
	.campaign-continue { padding: 0.75rem 0.85rem; }
	.nimble-campaign-view .campaign-search { min-height: 2.6rem; }
}
body.is-tablet :is(.campaign-party, .campaign-continue, .campaign-switch-btn, .campaign-search, .campaign-block-panel) { padding-left: 0.6rem; padding-right: 0.6rem; }

/* ============================================
   Player mode: GM / player campaigns, lore cards, battle notes
   ============================================ */

/* Side of the table: two big cards in New campaign and Campaign settings */
.nimble-role-pick { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.5rem; margin-bottom: 0.75rem; }
.nimble-role-pick .nimble-role-card {
	display: flex; flex-direction: column; align-items: flex-start; gap: 0.2rem; height: auto; padding: 0.75rem 0.8rem; text-align: left;
	white-space: normal; box-shadow: none; border: 1px solid var(--background-modifier-border); background: var(--background-primary);
}
.nimble-role-pick .nimble-role-card:hover { border-color: var(--interactive-accent); }
.nimble-role-pick .nimble-role-card.is-active { border-color: var(--interactive-accent); background: color-mix(in srgb, var(--interactive-accent) 12%, transparent); }
.nimble-role-pick .nimble-role-icon { display: inline-flex; color: var(--text-accent); margin-bottom: 0.15rem; }
.nimble-role-pick .nimble-role-icon svg { width: 22px; height: 22px; }
.nimble-role-pick .nimble-role-title { font-weight: 700; font-size: 0.95rem; }
.nimble-role-pick .nimble-role-desc { font-size: 0.78rem; color: var(--text-muted); line-height: 1.35; }
.nimble-role-heading { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 0.4rem; }
.nimble-campaign-settings .setting-item-control input[type="number"] { width: 5rem; }

/* The GM / Player pill in the switcher */
.campaign-role-pill {
	font-size: 0.66rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; padding: 0.05rem 0.4rem; border-radius: 999px;
	background: var(--background-modifier-hover); color: var(--text-muted); flex-shrink: 0;
}
.campaign-role-pill.role-player { background: color-mix(in srgb, var(--interactive-accent) 18%, transparent); color: var(--text-accent); }

/* Campaign notes: properties as a row of tags in reading view (reading-mode.ts sets the class). Editing keeps Obsidian's form. */
.nimble-props-tags .markdown-reading-view .metadata-container { margin-bottom: 1.1rem; }
.nimble-props-tags .markdown-reading-view .metadata-properties-heading,
.nimble-props-tags .markdown-reading-view .metadata-add-button,
.nimble-props-tags .markdown-reading-view .metadata-property-key { display: none; }
.nimble-props-tags .markdown-reading-view .metadata-container.is-collapsed .metadata-content { display: block; }
.nimble-props-tags .markdown-reading-view .metadata-properties { display: flex; flex-direction: row; flex-wrap: wrap; align-items: center; gap: 0.4rem; }
.nimble-props-tags .markdown-reading-view .metadata-property {
	display: inline-flex; align-items: center; gap: 0.45rem; width: auto; min-height: 1.9rem; margin: 0; padding: 0.15rem 0.7rem;
	border: 1px solid var(--background-modifier-border); border-radius: 999px; background: var(--background-secondary);
}
.nimble-props-tags .markdown-reading-view .metadata-property:hover { border-color: var(--background-modifier-border-hover); }
.nimble-props-tags .markdown-reading-view .metadata-property::before {
	content: attr(data-property-key); font-size: 0.64rem; font-weight: 800; line-height: 1; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-muted);
}
.nimble-props-tags .markdown-reading-view .metadata-property[data-property-key="first_met"]::before { content: "first met"; }
.nimble-props-tags .markdown-reading-view .metadata-property-value { width: auto; min-width: 0; flex: 0 1 auto; }
.nimble-props-tags .markdown-reading-view .metadata-property-value .metadata-input-longtext { min-height: 0; padding: 0; font-size: 0.85rem; font-weight: 600; line-height: 1.3; }
/* Number properties (level: 2) are a fixed-width input in Obsidian; size it to the number like the text values. */
.nimble-props-tags .markdown-reading-view .metadata-property-value .metadata-input-number {
	field-sizing: content; width: auto; min-width: 1ch; height: auto; padding: 0; border: none; background: none; appearance: textfield;
	font-size: 0.85rem; font-weight: 600; line-height: 1.3;
}
.nimble-props-tags .markdown-reading-view .metadata-property-value .metadata-link { padding: 0; font-size: 0.85rem; }
.nimble-props-tags .markdown-reading-view .metadata-property-value .metadata-link-flair { display: none; }
/* Bookkeeping the cards and panel already use, and anything left empty, stays out of the way. */
.nimble-props-tags .markdown-reading-view .metadata-property:is([data-property-key="nimble"], [data-property-key="portrait"], [data-property-key="portrait-position"], [data-property-key="cssclasses"], [data-property-key="title"], [data-property-key="order"]),
.nimble-props-tags .markdown-reading-view .metadata-property.nimble-prop-empty,
.nimble-props-tags .markdown-reading-view .metadata-property.nimble-prop-on-card,
.nimble-props-tags .markdown-reading-view .metadata-container.nimble-props-none { display: none; }

/* Party roster (player campaigns) */
.campaign-roster { margin-bottom: 0.6rem; }
.campaign-roster .campaign-roster-head { margin-top: 0; }
.campaign-roster-list { display: flex; flex-direction: column; gap: 0.3rem; }
.campaign-hero {
	display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 0.55rem; padding: 0.35rem 0.5rem;
	border-radius: 8px; color: var(--text-normal); text-decoration: none; border: 1px solid transparent;
}
.campaign-hero:hover { background: var(--background-modifier-hover); }
.campaign-hero.is-mine { border-color: color-mix(in srgb, var(--interactive-accent) 35%, var(--background-modifier-border)); background: color-mix(in srgb, var(--interactive-accent) 8%, transparent); padding: 0.5rem 0.6rem; }
.campaign-hero .campaign-hero-avatar { width: 28px; height: 28px; border-radius: 50%; flex-shrink: 0; }
.campaign-hero.is-mine .campaign-hero-avatar { width: 38px; height: 38px; }
.campaign-hero .campaign-hero-avatar.is-empty { display: inline-flex; align-items: center; justify-content: center; background: var(--background-modifier-hover); color: var(--text-muted); }
.campaign-hero .campaign-hero-avatar.is-empty svg { width: 15px; height: 15px; }
.campaign-hero-name { display: flex; align-items: center; gap: 0.35rem; font-weight: 600; font-size: 0.9rem; min-width: 0; }
.campaign-hero-name > span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.campaign-hero-you { font-size: 0.62rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; padding: 0 0.35rem; border-radius: 999px; background: var(--interactive-accent); color: var(--text-on-accent); flex-shrink: 0; }
.campaign-hero-sub { font-size: 0.76rem; color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.campaign-hero-hp { position: relative; height: 14px; margin-top: 0.25rem; border-radius: 7px; background: var(--background-modifier-border); overflow: hidden; }
.campaign-hero-hp-fill { position: absolute; inset: 0 auto 0 0; width: var(--hp-pct, 100%); background: var(--nimble-hp, #c0392b); border-radius: 7px; }
/* Low HP looks more urgent than healthy: the same red, darker. */
.campaign-hero-hp-fill.is-low { background: color-mix(in srgb, var(--nimble-hp, #c0392b) 72%, #000); }
.campaign-hero-hp-text { position: relative; display: block; text-align: center; font-size: 0.66rem; font-weight: 700; line-height: 14px; color: var(--text-normal); font-variant-numeric: tabular-nums; }
.campaign-roster-empty { width: 100%; }
.campaign-roster-note { margin-top: 0.35rem; font-size: 0.76rem; color: var(--text-muted); }
.campaign-roster-list + .campaign-roster-empty { margin-top: 0.45rem; }
.campaign-hero.is-plain { cursor: default; }
@media (pointer: coarse) { .campaign-hero { min-height: 2.8rem; } }

/* Lore card: what a hero could know about a creature */
.nimble-lore-card .monster-meta { color: var(--text-muted); font-size: 0.85rem; }
.nimble-lore-card .lore-tags { display: flex; flex-wrap: wrap; gap: 0.3rem; margin: 0.45rem 0 0.2rem; }
.nimble-lore-card .lore-tag { font-size: 0.72rem; padding: 0.05rem 0.5rem; border-radius: 999px; background: var(--background-modifier-hover); color: var(--text-muted); }
.nimble-lore-card .lore-empty { color: var(--text-faint); font-style: italic; }
.nimble-lore-card .lore-sources { display: flex; flex-wrap: wrap; align-items: center; gap: 0.3rem; margin-top: 0.7rem; }
.nimble-lore-card .lore-credit { font-size: 0.72rem; color: var(--text-faint); }
/* Your notes on a creature, under its lore in the bestiary */
.nimble-creature-notes { margin-top: 0.75rem; padding: 0.6rem 0.85rem 0.3rem; border: 1px solid var(--background-modifier-border); border-left: 3px solid var(--interactive-accent); border-radius: 8px; background: var(--background-primary); }
.nimble-creature-notes-head { display: flex; align-items: center; gap: 0.4rem; font-weight: 600; font-size: 0.85rem; }
.nimble-creature-notes-icon { display: inline-flex; color: var(--text-accent); }
.nimble-creature-notes-icon svg { width: 15px; height: 15px; }
.nimble-creature-notes-title { flex: 1; }
.nimble-creature-notes-body { font-size: 0.88rem; }
.nimble-creature-notes-body :is(h1, h2, h3, h4, h5, h6) { font-size: 0.78rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); margin: 0.8rem 0 0.2rem; }
.nimble-creature-notes-body :is(ul, ol) { margin: 0.2rem 0; }
.nimble-creature-notes-body p { margin: 0.3rem 0; }
.nimble-bestiary .bestiary-row-line { display: flex; align-items: center; gap: 0.4rem; min-width: 0; }
.nimble-bestiary .bestiary-row-line .bestiary-row-meta { flex: 1; min-width: 0; }
.nimble-creature-notes-body > :first-child { margin-top: 0.4rem; }
.nimble-creature-notes-empty { color: var(--text-faint); font-style: italic; padding: 0.3rem 0 0.4rem; }
.nimble-bestiary .bestiary-level.bestiary-lore-icon { display: inline-flex; align-items: center; justify-content: center; color: var(--text-faint); background: transparent; }
.nimble-bestiary .bestiary-lore-icon svg { width: 15px; height: 15px; }

/* Battle notes: a player's encounter block (core/battle-notes.ts), the GM block's card in the game's look
   (Nimble's paper, 5e's page). How it went is a tag like the GM's rating (dark, white text; 5e's red), its
   colour on the icon; unset, a quiet outlined chip. */
.ev-battle-notes :is(.encounter-block-head, .dnd5e-encounter-head) button.battle-outcome {
	display: inline-flex; align-items: center; height: 24px; padding: 0 9px; border: 0; border-radius: var(--ev-r-chip); box-shadow: none; cursor: pointer;
	background: var(--ev-bar, var(--ev-accent)); color: var(--ev-on-bar, var(--ev-on-accent)); font: 700 11.5px/normal var(--ev-font-ui); letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap;
	--ev-pill-icon: 13px; --ev-pill-gap: 5px;
}
.ev-battle-notes :is(.encounter-block-head, .dnd5e-encounter-head) button.battle-outcome:hover { background: color-mix(in srgb, var(--ev-bar, var(--ev-accent)) 88%, var(--ev-text)); }
.ev-battle-notes .battle-outcome .ev-pill-icon { color: var(--outcome-dot, currentColor); }
.ev-battle-notes .battle-outcome.outcome-won { --outcome-dot: #6cc48a; }
.ev-battle-notes .battle-outcome.outcome-fled { --outcome-dot: #e3cd5a; }
.ev-battle-notes .battle-outcome.outcome-lost { --outcome-dot: #ff7a6b; }
.ev-battle-notes .battle-outcome.outcome-parley { --outcome-dot: #9fc3ec; }
.ev-battle-notes :is(.encounter-block-head, .dnd5e-encounter-head) button.battle-outcome.outcome-unset { background: transparent; color: var(--ev-text-2); box-shadow: inset 0 0 0 1px var(--ev-line-strong); font-weight: 600; letter-spacing: 0; text-transform: none; }
.ev-battle-notes :is(.encounter-block-head, .dnd5e-encounter-head) button.battle-outcome.outcome-unset:hover { background: var(--ev-surface-2); }
.nimble-battle-notes .battle-foe { display: inline-flex; align-items: center; gap: 0.3rem; }
.nimble-battle-notes .battle-foe-count { display: inline-flex; align-items: center; padding-left: 0.6em; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--ev-text-2); }
.nimble-battle-notes .battle-foe-name { display: inline-flex; align-items: center; padding-right: 0.75em; }
.ev-battle-notes .battle-facts { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 2px; font: 500 12.5px/18px var(--ev-font-ui); color: var(--ev-text-2); }
.ev-battle-notes .battle-fact { display: inline-flex; align-items: center; gap: 5px; min-width: 0; }
.ev-battle-notes .battle-fact-icon { display: inline-flex; color: var(--ev-text-2); }
.ev-battle-notes .battle-fact-icon svg { width: 14px; height: 14px; }
/* 5e: the facts and notes under the roster's dotted rows, Edit at the foot like Run. */
.dnd5e-battle-notes .battle-facts { margin-top: 0.15rem; }
.dnd5e-battle-notes .battle-fact-icon { color: var(--ev-accent-text); }
.dnd5e-battle-notes .dnd5e-encounter-empty { color: var(--text-faint); font-style: italic; padding: 0.22rem 0; }
.nimble-battle-modal .battle-modal-heading { margin: 4px 0 -6px; font: 700 12.5px/normal var(--ev-font-display); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
.nimble-battle-modal .battle-modal-foes { display: flex; flex-direction: column; gap: 0.2rem; margin-bottom: 0.4rem; }
.nimble-battle-modal .battle-modal-foe { display: grid; grid-template-columns: auto 1.6rem auto minmax(0, 1fr) auto; align-items: center; gap: 0.3rem; }
.nimble-battle-modal .battle-modal-count { text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
.nimble-battle-modal .battle-modal-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-battle-modal .battle-modal-add { width: 100%; }
.nimble-battle-modal .battle-modal-outcome { display: flex; flex-wrap: wrap; }
.nimble-battle-modal .battle-modal-notes textarea { width: 100%; min-height: 5rem; }
.nimble-battle-modal .battle-modal-notes { flex-wrap: wrap; }
.nimble-battle-modal .battle-modal-notes .setting-item-control { flex: 1 1 100%; }
.tracker-player-note button { margin-top: 0.5rem; }
@media (max-width: 480px) {
	.nimble-role-pick { grid-template-columns: minmax(0, 1fr); }
}
body.is-tablet :is(.battle-outcome, .nimble-role-card) { padding-left: 0.7rem; padding-right: 0.7rem; }

/* ============================================
   BOXES: ```box read-aloud / look / treasure / trap / secret …
   --box-color comes from the fence line (or the type's preset).
   ============================================ */

.nimble-box {
	--box-tint: color-mix(in srgb, var(--box-color) 9%, var(--background-primary));
	--box-edge: color-mix(in srgb, var(--box-color) 55%, transparent);
	margin: 0.9rem 0;
	border-radius: 10px;
	background: var(--box-tint);
	border: 1px solid color-mix(in srgb, var(--box-color) 28%, transparent);
	border-left: 4px solid var(--box-color);
	overflow: hidden;
}
.nimble-box-head { display: flex; align-items: center; gap: 0.5rem; padding: 0.5rem 0.75rem 0.15rem 0.6rem; }
.nimble-box-icon {
	flex-shrink: 0; display: inline-flex; align-items: center; justify-content: center;
	width: 1.9rem; height: 1.9rem; padding: 0; border-radius: 8px; box-shadow: none; border: none; cursor: pointer;
	background: color-mix(in srgb, var(--box-color) 18%, transparent); color: var(--box-color);
	transition: transform 0.12s, background 0.12s;
}
.nimble-box-icon:hover { background: color-mix(in srgb, var(--box-color) 30%, transparent); transform: scale(1.06); }
.nimble-box-icon svg { width: 17px; height: 17px; stroke-width: 2.2; }
/* Obsidian's phone and tablet buttons pad 4px 20px, which left the icon no room; this outranks that. */
.nimble-box-head button.nimble-box-icon { padding: 0; }
.nimble-box-icon svg { flex: none; }
.nimble-box-title {
	flex: 1; min-width: 0; cursor: pointer; user-select: none;
	font-size: 0.74rem; font-weight: 800; letter-spacing: 0.09em; text-transform: uppercase;
	color: color-mix(in srgb, var(--box-color) 80%, var(--text-normal));
}
.nimble-box-chevron { display: inline-flex; color: var(--text-faint); cursor: pointer; transition: transform 0.15s; }
.nimble-box-chevron svg { width: 15px; height: 15px; }
.nimble-box.is-folded .nimble-box-chevron { transform: rotate(-90deg); }
.nimble-box.is-folded .nimble-box-body { display: none; }
.nimble-box.is-folded .nimble-box-head { padding-bottom: 0.5rem; }
.nimble-box-body { padding: 0.2rem 1.1rem 0.8rem 0.95rem; line-height: 1.6; }
.nimble-box-body > :first-child { margin-top: 0.15rem; }
.nimble-box-body > :last-child { margin-bottom: 0; }
.nimble-box-body p { margin: 0.35rem 0; }
.nimble-box-body ul, .nimble-box-body ol { margin: 0.3rem 0; padding-inline-start: 1.45rem; }
.nimble-box-body li { margin: 0.18rem 0; }
.nimble-box-body li::marker { color: var(--box-color); }
.nimble-box-body table { margin: 0.35rem 0; font-size: 0.92em; width: 100%; }
.nimble-box-body th { color: color-mix(in srgb, var(--box-color) 75%, var(--text-normal)); }
.nimble-box-body strong { color: var(--text-normal); }
.nimble-box-empty { color: var(--text-faint); font-style: italic; font-size: 0.85rem; }
.nimble-box.is-bold .nimble-box-body { font-weight: 600; }
.nimble-box.is-italic .nimble-box-body { font-style: italic; }

/* Fonts */
.box-font-serif .nimble-box-body { font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Book Antiqua", serif; font-size: 1.06em; }
.box-font-hand .nimble-box-body { font-family: "Bradley Hand", "Segoe Print", "Chalkboard SE", "Comic Neue", "Patrick Hand", cursive; font-size: 1.1em; }
.box-font-mono .nimble-box-body { font-family: var(--font-monospace); font-size: 0.92em; }

/* The read-aloud is where a GM's eye goes first: give it room. */
.nimble-box.box-read-aloud .nimble-box-body { font-size: 1.08em; line-height: 1.65; }
.nimble-box.box-read-aloud.box-font-serif .nimble-box-body { font-size: 1.12em; }

/* Banner: a solid header strip */
.nimble-box.box-style-banner { border-left-width: 1px; background: var(--background-primary); }
.box-style-banner .nimble-box-head { background: var(--box-color); padding: 0.4rem 0.75rem 0.4rem 0.6rem; }
.box-style-banner .nimble-box-icon { background: rgba(255,255,255,0.18); color: #fff; }
.box-style-banner .nimble-box-title, .box-style-banner .nimble-box-chevron { color: #fff; }
.box-style-banner .nimble-box-body { padding-top: 0.6rem; padding-left: 1rem; }

/* Old note: warm paper, serif, a soft ragged shadow */
.nimble-box.box-style-parchment {
	--paper: #f3e6c8; --ink: #3b2a17;
	background: radial-gradient(ellipse at 20% 0%, rgba(255,255,255,.35), transparent 55%), radial-gradient(ellipse at 100% 100%, rgba(120,80,30,.16), transparent 60%), var(--paper);
	color: var(--ink); border: 1px solid #c9b28a; border-left: 1px solid #c9b28a; border-radius: 4px;
	box-shadow: 0 1px 0 rgba(0,0,0,.05), 0 6px 16px -8px rgba(60,40,10,.45), inset 0 0 28px rgba(120,80,30,.18);
}
.box-style-parchment .nimble-box-title { color: #7a4f1d; }
.box-style-parchment .nimble-box-icon { background: rgba(122,79,29,.12); color: #7a4f1d; }
.box-style-parchment .nimble-box-body, .box-style-parchment .nimble-box-body strong { color: var(--ink); }
.box-style-parchment .nimble-box-body a { color: #8a3b12; }
.box-style-parchment .nimble-box-body li::marker { color: #7a4f1d; }
.box-style-parchment.box-font-sans .nimble-box-body { font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif; }

/* Letter: lined paper */
.nimble-box.box-style-letter {
	--ink: #23324d;
	background: repeating-linear-gradient(transparent 0 1.55em, rgba(70,110,170,.18) 1.55em calc(1.55em + 1px)), #fbfaf5;
	color: var(--ink); border: 1px solid #dcd6c6; border-left: 3px double #e08b8b; border-radius: 3px;
	box-shadow: 0 4px 14px -8px rgba(0,0,0,.4);
}
.box-style-letter .nimble-box-body { line-height: 1.55em; color: var(--ink); }
.box-style-letter .nimble-box-body strong { color: var(--ink); }
.box-style-letter .nimble-box-title { color: #6b5a3a; }
.box-style-letter .nimble-box-icon { background: rgba(35,50,77,.08); color: #23324d; }

/* Stone: an engraved slab */
.nimble-box.box-style-stone {
	background: linear-gradient(160deg, #4a4f57, #33373d 60%, #2b2e33); color: #e9e6df;
	border: 1px solid #22252a; border-left: 1px solid #22252a; border-radius: 6px;
	box-shadow: inset 0 1px 0 rgba(255,255,255,.08), inset 0 -2px 6px rgba(0,0,0,.35), 0 4px 12px -6px rgba(0,0,0,.6);
}
.box-style-stone .nimble-box-title { color: color-mix(in srgb, var(--box-color) 55%, #f3efe6); text-shadow: 0 1px 0 rgba(0,0,0,.6); letter-spacing: 0.14em; }
.box-style-stone .nimble-box-icon { background: rgba(0,0,0,.25); color: color-mix(in srgb, var(--box-color) 60%, #fff); box-shadow: inset 0 1px 2px rgba(0,0,0,.5); }
.box-style-stone .nimble-box-body, .box-style-stone .nimble-box-body strong { color: #e9e6df; }
.box-style-stone .nimble-box-body a { color: color-mix(in srgb, var(--box-color) 50%, #fff); }

/* Minimal: just a rule and an icon */
.nimble-box.box-style-minimal { background: transparent; border: none; border-left: 2px solid var(--box-edge); border-radius: 0; }
.box-style-minimal .nimble-box-head { padding-top: 0.2rem; }
.box-style-minimal .nimble-box-icon { background: transparent; }

@media (pointer: coarse) {
	.nimble-box-icon { width: 2.3rem; height: 2.3rem; }
	.nimble-box-body { padding-left: 1rem; }
}

/* NPCs: chips for links to NPC notes, a light underline for plain mentions */
a.internal-link.nimble-npc-link {
	display: inline-flex; align-items: baseline; gap: 0.25em; text-decoration: none; line-height: 1.3;
	/* A little shorter than the text line, with room above and below, so pills on wrapped lines don't touch. */
	padding: 0 0.4em 0 0.35em; margin: 0.15em 0.08em 0.15em 0; border-radius: 999px; position: relative; top: -0.05em;
	background: color-mix(in srgb, #22a35a 14%, transparent); color: color-mix(in srgb, #22a35a 70%, var(--text-normal));
	border: 1px solid color-mix(in srgb, #22a35a 30%, transparent); font-weight: 600; font-size: 0.95em;
}
a.internal-link.nimble-npc-link:hover { background: color-mix(in srgb, #22a35a 24%, transparent); text-decoration: none; }
.nimble-npc-icon { display: inline-flex; align-self: center; }
.nimble-npc-icon svg { width: 0.85em; height: 0.85em; stroke-width: 2.5; }
a.internal-link.nimble-npc-mention, a.internal-link.nimble-npc-mention:hover { text-decoration: none; }
a.internal-link.nimble-npc-mention {
	color: inherit; border-bottom: 2px dotted color-mix(in srgb, #22a35a 70%, transparent);
}
a.internal-link.nimble-npc-mention:hover { color: color-mix(in srgb, #22a35a 75%, var(--text-normal)); }
.nimble-slash-swatch { width: 0.8rem; height: 0.8rem; border-radius: 3px; flex-shrink: 0; margin-left: auto; }

/* NPCs in Live Preview */
.nimble-npc-lp-link .cm-hmd-internal-link, .nimble-npc-lp-link .cm-underline, .cm-hmd-internal-link.nimble-npc-lp-link {
	color: color-mix(in srgb, #22a35a 70%, var(--text-normal)); font-weight: 600; text-decoration: none;
	background: color-mix(in srgb, #22a35a 14%, transparent); border-radius: 4px;
}
.nimble-npc-lp-icon { display: inline-flex; vertical-align: -0.1em; margin-right: 0.15em; color: #22a35a; }
.nimble-npc-lp-icon svg { width: 0.85em; height: 0.85em; stroke-width: 2.5; }
.nimble-npc-lp-mention { border-bottom: 2px dotted color-mix(in srgb, #22a35a 70%, transparent); }
.nimble-npc-lp-link .cm-underline, .nimble-npc-lp-link .cm-hmd-internal-link { padding: 0 0.15em; }
/* No link underline on NPC links and mentions. Obsidian's strongest underline rule is
   .markdown-source-view.mod-cm6 .cm-hmd-internal-link .cm-underline:hover, so these go one class further. */
.markdown-source-view.mod-cm6 .cm-line :is(.nimble-npc-lp-link, .nimble-npc-lp-mention) :is(.cm-underline, .cm-hmd-internal-link),
.markdown-source-view.mod-cm6 .cm-line :is(.nimble-npc-lp-link, .nimble-npc-lp-mention) :is(.cm-underline, .cm-hmd-internal-link):hover,
.markdown-source-view.mod-cm6 .cm-line :is(.cm-hmd-internal-link, .cm-underline):is(.nimble-npc-lp-link, .nimble-npc-lp-mention),
.markdown-source-view.mod-cm6 .cm-line :is(.cm-hmd-internal-link, .cm-underline):is(.nimble-npc-lp-link, .nimble-npc-lp-mention):hover,
.markdown-source-view.mod-cm6 .cm-line .nimble-npc-lp-mention { text-decoration: none; }

/* Links to other campaign notes: a pill with the kind's icon (npc-links.ts, npc-live-preview.ts), coloured by kind.
   Green is for NPCs and purple for the party, so a finished quest stays orange (its tick says it's done) and chapters stay grey. */
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon) { --pill: var(--text-muted); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon).kind-quest { --pill: var(--color-orange); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon):is(.kind-location, .kind-map) { --pill: var(--color-blue); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon).kind-character { --pill: var(--color-purple); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon):is(.kind-monster, .kind-creature, .kind-combat) { --pill: var(--color-red); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon).kind-handout { --pill: var(--color-yellow); }
:is(.nimble-note-link, .nimble-note-lp-link, .nimble-note-lp-icon).is-quest-failed { --pill: var(--text-faint); }
a.internal-link.nimble-note-link {
	display: inline-flex; align-items: baseline; gap: max(0.25em, 3px); text-decoration: none; line-height: 1.3;
	/* A little shorter than the text line, with room above and below, so pills on wrapped lines don't touch. */
	padding: 0 0.4em 0 0.35em; margin: 0.15em 0.08em 0.15em 0; border-radius: 999px; position: relative; top: -0.05em;
	background: color-mix(in srgb, var(--pill) 14%, transparent); color: color-mix(in srgb, var(--pill) 70%, var(--text-normal));
	border: 1px solid color-mix(in srgb, var(--pill) 30%, transparent); font-weight: 600; font-size: 0.95em;
}
a.internal-link.nimble-note-link:hover { background: color-mix(in srgb, var(--pill) 24%, transparent); text-decoration: none; }
.nimble-note-icon { display: inline-flex; align-self: center; }
.nimble-note-icon svg { width: 0.85em; height: 0.85em; stroke-width: 2.5; }
.nimble-note-lp-link .cm-hmd-internal-link, .nimble-note-lp-link .cm-underline, .cm-hmd-internal-link.nimble-note-lp-link {
	color: color-mix(in srgb, var(--pill) 70%, var(--text-normal)); font-weight: 600; text-decoration: none;
	background: color-mix(in srgb, var(--pill) 14%, transparent); border-radius: 4px; padding: 0 0.15em;
}
.nimble-note-lp-icon { display: inline-flex; vertical-align: -0.1em; margin-right: 0.15em; color: var(--pill); }
.nimble-note-lp-icon svg { width: 0.85em; height: 0.85em; stroke-width: 2.5; }
.markdown-source-view.mod-cm6 .cm-line .nimble-note-lp-link :is(.cm-underline, .cm-hmd-internal-link),
.markdown-source-view.mod-cm6 .cm-line .nimble-note-lp-link :is(.cm-underline, .cm-hmd-internal-link):hover,
.markdown-source-view.mod-cm6 .cm-line :is(.cm-hmd-internal-link, .cm-underline).nimble-note-lp-link,
.markdown-source-view.mod-cm6 .cm-line :is(.cm-hmd-internal-link, .cm-underline).nimble-note-lp-link:hover { text-decoration: none; }

/* ---------- Box editor: a small tabbed panel ---------- */
.nimble-popover.nimble-box-editor { padding: 0; width: 304px; overflow: hidden; border-radius: 12px; font-size: 0.86rem; }
.nimble-popover.nimble-box-editor.is-sheet { width: 100%; }
.nimble-popover.nimble-box-editor .bxe-head { display: flex; align-items: center; gap: 0.55rem; padding: 0.75rem 0.85rem 0.55rem; }
.nimble-popover.nimble-box-editor .bxe-badge {
	flex-shrink: 0; width: 2rem; height: 2rem; border-radius: 9px; display: inline-flex; align-items: center; justify-content: center;
	background: color-mix(in srgb, var(--box-color) 20%, transparent); color: var(--box-color);
}
.nimble-popover.nimble-box-editor .bxe-badge svg { width: 17px; height: 17px; stroke-width: 2.2; }
.nimble-popover.nimble-box-editor .bxe-title {
	flex: 1; min-width: 0; height: 2rem; padding: 0 0.4rem; border: 1px solid transparent; border-radius: 6px; background: transparent;
	font-weight: 600; font-size: 0.95rem; box-shadow: none;
