	.markdown-source-view.mod-cm6 .cm-embed-block.cm-preview-code-block:is(.cm-lang-box, .cm-lang-nimble-encounter, .cm-lang-nimble-map, .cm-lang-nimble-campaign, .cm-lang-nimble) > .edit-block-button { opacity: 1; }
