	border: none; border-top: 1px solid var(--background-modifier-border); padding: 0.55rem 0.8rem; vertical-align: top; text-align: left;
}
:is(.nimble-box-body, body.nimble-tables .markdown-rendered, body.nimble-tables .cm-table-widget) table:not(.dnd5e-card-table) thead th {
	border-top: none; background: color-mix(in srgb, var(--tbl-accent) 10%, var(--background-secondary));
