:is(.nimble-sheet, .ev-vitals) .ns-meter-ghost.is-gain { background: var(--ns-gain); }
:is(.nimble-sheet, .ev-vitals) .ns-meter-extra-fill {
	position: absolute; top: 0; bottom: 0; left: var(--ns-from, 0%); width: var(--ns-fill, 0%); max-width: calc(100% - var(--ns-from, 0%));
	background: repeating-linear-gradient(135deg, color-mix(in srgb, var(--ns-temp) var(--ns-shade), #000) 0 6px, color-mix(in srgb, var(--ns-temp) var(--ns-shade-2), #000) 6px 12px);
}
:is(.nimble-sheet, .ev-vitals) .ns-meter-nums {
	position: relative; display: flex; align-items: center; justify-content: center; gap: 0.2rem; height: 100%;
	font-variant-numeric: tabular-nums; color: #fff; line-height: normal; text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
}
:is(.nimble-sheet, .ev-vitals) .ns-meter-cur { font-size: 1.15rem; font-weight: 800; }
:is(.nimble-sheet, .ev-vitals) .ns-meter-slash { color: rgba(255, 255, 255, 0.85); }
:is(.nimble-sheet, .ev-vitals) .ns-meter-max { font-size: 0.9rem; font-weight: 700; color: #fff; }
:is(.nimble-sheet, .ev-vitals) .ns-meter-delta { margin-left: 0.35rem; padding: 0 0.4rem; border-radius: 999px; font-size: 0.78rem; font-weight: 800; line-height: 1.35; color: #1d1405; text-shadow: none; animation: ns-delta-pop 0.18s ease-out; }
:is(.nimble-sheet, .ev-vitals) .ns-meter-delta.is-loss { background: var(--ns-loss); }
:is(.nimble-sheet, .ev-vitals) .ns-meter-delta.is-gain { background: var(--ns-gain); }
@keyframes ns-delta-pop { from { transform: scale(0.7); } to { transform: scale(1); } }
:is(.nimble-sheet, .ev-vitals) .ns-meter-plus { margin-left: 0.25rem; font-size: 0.8rem; font-weight: 800; color: #fff; }
:is(.nimble-sheet, .ev-vitals) .ns-meter.is-low .ns-meter-label, .nimble-sheet.is-dying .ns-meter.is-hp .ns-meter-label { color: var(--ns-wound); }
/* Narrow (the Character panel, phones): the bar itself opens the calculator, so its button goes. */
@container nimble-sheet (max-width: 400px) {
	.nimble-sheet .ns-meter-calc.ns-step { display: none; }
	.nimble-sheet .ns-meters { padding: 0.75rem; }
}
@media (pointer: coarse) {
	:is(.nimble-sheet, .ev-vitals) button.ns-meter-bar { height: 2.5rem; }
	:is(.nimble-sheet, .ev-vitals) .ns-meter-step.ns-step, :is(.nimble-sheet, .ev-vitals) .ns-meter-calc.ns-step { width: 2.5rem; height: 2.5rem; }
}


/* Wounds: a row of pips in the Hit points header */
.nimble-sheet .ns-wounds { display: inline-flex; align-items: center; gap: 0.45rem; margin-left: auto; }
.nimble-sheet .ns-wounds-tab { display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); }
.nimble-sheet .ns-wounds-drop { display: inline-flex; color: var(--ns-wound); }
.nimble-sheet .ns-wounds-drop svg { width: 11px; height: 11px; fill: currentColor; }
.nimble-sheet .ns-wounds-track { display: inline-flex; align-items: center; gap: 0.2rem; }
.nimble-sheet .ns-pip { width: 1rem; height: 1rem; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; }
.nimble-sheet button.ns-pip { position: relative; border: 2px solid color-mix(in srgb, var(--ns-wound) 45%, var(--ns-card-line)); background: transparent; }
.nimble-sheet .ns-wounds button.ns-pip:not(.is-skull)::before { inset: -2px; background: var(--ns-wound); }
.nimble-sheet button.ns-pip:hover { border-color: var(--ns-wound); }
.nimble-sheet button.ns-pip.is-on { border-color: var(--ns-wound); }
.nimble-sheet button.ns-pip.is-skull { border: none; width: 1.2rem; height: 1.2rem; color: var(--text-faint); }
.nimble-sheet button.ns-pip.is-skull svg { width: 16px; height: 16px; }
.nimble-sheet button.ns-pip.is-skull.is-on { color: var(--ns-wound); background: transparent; }
.nimble-sheet .ns-wounds-count { font-size: 0.72rem; font-weight: 700; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.nimble-sheet.is-dying .ns-wounds-count { color: var(--ns-wound); }
.nimble-sheet .ns-wounds-max { width: 5.5rem; text-align: center; }
@media (pointer: coarse) { .nimble-sheet .ns-pip { width: 1.35rem; height: 1.35rem; } }

/* Conditions, chips and steppers (the sheet and the tracker's quick look) */
.nimble-sheet .ns-conds-row {
	display: flex; flex-wrap: wrap; align-items: center; gap: 0.45rem 0.7rem; margin-bottom: 0.75rem; padding: 0.55rem 0.8rem;
	border: 1px solid var(--ns-card-line); border-radius: 16px; background: var(--ns-card);
}
.nimble-sheet .ns-conds-row.has-conds { border-color: color-mix(in srgb, var(--ns-wound) 35%, var(--ns-card-line)); background: color-mix(in srgb, var(--ns-wound) 5%, var(--ns-card)); }
.nimble-sheet .ns-conds-label { flex: 0 0 auto; }
.nimble-sheet .ns-conds-none { font-size: 0.82rem; color: var(--text-faint); }
.nimble-sheet .ns-chip {
	display: inline-flex; align-items: center; gap: 0.4rem; min-height: 2rem; padding: 0.2rem 0.7rem;
	border: 1px solid var(--background-modifier-border); border-radius: 999px; background: var(--ns-soft);
}
.nimble-sheet button.ns-chip { border: 1px solid var(--background-modifier-border); background: var(--ns-soft); padding: 0.2rem 0.7rem; }
.nimble-sheet button.ns-chip:hover { border-color: var(--ns-accent); }
.nimble-sheet .ns-chip-label { display: inline-flex; align-items: center; font-size: 0.66rem; font-weight: 800; line-height: 1; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); white-space: nowrap; }
.nimble-sheet button.ns-chip-label:hover { color: var(--text-accent); }
.nimble-sheet .ns-chip-value { display: inline-flex; align-items: center; font-weight: 800; line-height: 1; font-variant-numeric: tabular-nums; white-space: nowrap; }
.nimble-sheet .ns-chip.is-edit input { width: 4rem; height: 1.6rem; padding: 0 0.3rem; }
:is(.nimble-sheet, .ev-vitals) .ns-step {
	width: 1.65rem; height: 1.65rem; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
	padding: 0; border-radius: 50%; line-height: 0; color: var(--text-muted);
}
:is(.nimble-sheet, .ev-vitals) .ns-step svg { width: 13px; height: 13px; stroke-width: 2.6; display: block; }
.nimble-sheet .ns-cond-x { display: inline-flex; align-items: center; justify-content: center; padding: 0; line-height: 0; }
.nimble-sheet .ns-cond-x svg { width: 12px; height: 12px; stroke-width: 2.4; display: block; }
.nimble-sheet .ns-cond-name { display: inline-flex; align-items: center; line-height: 1; }
:is(.nimble-sheet, .ev-vitals) button.ns-step { background: var(--background-modifier-hover); }
:is(.nimble-sheet, .ev-vitals) button.ns-step:hover:not(:disabled) { background: var(--ns-accent); color: var(--text-on-accent); }
/* Die shapes (die-shape.ts), wherever they show: the sheet's class dice in the class dice colour (Settings), Camp's Hit Dice. */
.ns-die { display: inline-grid; place-items: center; width: 1.65rem; height: 1.65rem; color: var(--ns-class-dice, #d4a72c); }
.ns-die > * { grid-area: 1 / 1; }
.ns-die-svg { display: block; width: 100%; height: 100%; overflow: visible; }
.ns-die-body { fill: currentColor; stroke: color-mix(in srgb, currentColor 65%, #000); stroke-width: 1.3; stroke-linejoin: round; }
.ns-die-face { fill: none; stroke: color-mix(in srgb, currentColor 55%, #000); stroke-width: 1; stroke-linejoin: round; opacity: 0.55; }
.ns-die-num { font-size: 0.72rem; font-weight: 800; line-height: normal; font-variant-numeric: tabular-nums; color: var(--ns-class-dice-ink, #24180a); }
.ns-die.is-d4 .ns-die-num { padding-top: 0.3rem; font-size: 0.66rem; }
.ns-die.is-d20 .ns-die-num, .ns-die.is-d12 .ns-die-num { font-size: 0.64rem; }
.ns-die.is-empty .ns-die-body { fill: transparent; stroke: color-mix(in srgb, currentColor 60%, transparent); stroke-dasharray: 2.2 2; }
.ns-die.is-empty .ns-die-face, .ns-die.has-value .ns-die-face { display: none; }
.ns-die.is-clickable { cursor: pointer; border-radius: 4px; }
.ns-die.is-clickable:hover { filter: brightness(1.1); }
.ns-die.is-clickable:focus-visible { outline: 2px solid var(--background-modifier-border-focus); }
.nimble-sheet .ns-conds, .nimble-sheet .ns-langs { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 0.3rem; }
.nimble-sheet .ns-cond, .nimble-sheet .ns-lang {
	display: inline-flex; align-items: center; gap: 0.1rem; height: 1.9rem; padding: 0 0.25rem 0 0.65rem; border-radius: 999px;
	background: color-mix(in srgb, var(--ns-wound) 13%, var(--ns-paper)); border: 1px solid color-mix(in srgb, var(--ns-wound) 40%, transparent);
	font-size: 0.82rem; font-weight: 700;
}
.nimble-sheet .ns-lang { background: var(--ns-soft); border-color: var(--background-modifier-border); font-weight: 600; }
/* The name's capitals sit a pixel high in the chip; bring them down to the × on its centre line. */
.nimble-sheet .ns-lang > span:first-child { position: relative; top: 1px; }
.nimble-sheet .ns-cond-name:hover { text-decoration: underline; }
.nimble-sheet .ns-cond-x { width: 1.4rem; height: 1.4rem; border-radius: 50%; color: var(--text-muted); font-size: 1rem; }
.nimble-sheet .ns-cond-x:hover { color: var(--text-error); background: var(--background-modifier-hover); }
.nimble-sheet .ns-cond-add { display: inline-flex; align-items: center; gap: 0.25rem; height: 1.9rem; min-width: 1.9rem; justify-content: center; padding: 0 0.55rem; border-radius: 999px; color: var(--text-muted); font-size: 0.8rem; font-weight: 600; }
.nimble-sheet button.ns-cond-add { border: 1px dashed var(--background-modifier-border-hover); padding: 0 0.55rem; }
.nimble-sheet button.ns-cond-add:hover { color: var(--text-accent); border-color: var(--ns-accent); }
.nimble-sheet .ns-cond-add svg { width: 14px; height: 14px; }


.nimble-sheet .ns-empty-note { margin-top: 0.6rem; font-size: 0.8rem; color: var(--text-muted); }

/* Tabs (sticky while scrolling the note) */
.nimble-sheet .ns-tabs {
	position: sticky; top: 0; z-index: 2; display: flex; margin-top: 1rem;
	background: var(--background-primary); border-bottom: 1px solid var(--background-modifier-border);
}
.nimble-sheet .ns-tab {
	flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 0.12rem;
	padding: 0.45rem 0.2rem 0.4rem; color: var(--text-muted); border-bottom: 2.5px solid transparent; margin-bottom: -1px; border-radius: 0;
}
.nimble-sheet button.ns-tab { padding: 0.45rem 0.2rem 0.4rem; border-bottom: 2.5px solid transparent; }
.nimble-sheet button.ns-tab:hover { color: var(--text-normal); }
.nimble-sheet button.ns-tab.is-active { color: var(--text-accent); border-bottom-color: var(--ns-accent); }
.nimble-sheet .ns-tab-icon { display: inline-flex; }
.nimble-sheet .ns-tab-icon svg { width: 17px; height: 17px; }
.nimble-sheet .ns-tab-label { font-size: 0.74rem; font-weight: 700; letter-spacing: 0.02em; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-sheet .ns-tab-count { font-size: 0.62rem; font-weight: 700; color: var(--text-faint); font-variant-numeric: tabular-nums; }
.nimble-sheet .ns-tab-count.is-over { color: var(--text-error); }
@container nimble-sheet (min-width: 560px) {
	.nimble-sheet .ns-tab { flex-direction: row; justify-content: center; gap: 0.4rem; }
	.nimble-sheet .ns-tab-label { font-size: 0.86rem; }
}
.nimble-sheet .ns-panel { padding-top: 0.35rem; min-height: 6rem; }
.nimble-sheet .ns-section { margin-top: 0.75rem; }
.nimble-sheet .ns-section-head { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; padding: 0 0.1rem 0.25rem; border-bottom: 2px solid var(--ns-line); }
.nimble-sheet .ns-section-title { font-size: 0.74rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.07em; color: var(--text-muted); }
.nimble-sheet .ns-panel-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 0.45rem; margin-top: 0.6rem; }
.nimble-sheet .ns-panel-note { font-size: 0.8rem; color: var(--text-muted); }
.nimble-sheet .ns-add { display: inline-flex; align-items: center; gap: 0.3rem; height: 1.8rem; padding: 0 0.65rem; border-radius: 999px; font-size: 0.8rem; font-weight: 700; color: var(--text-accent); }
.nimble-sheet button.ns-add { padding: 0 0.65rem; background: color-mix(in srgb, var(--ns-accent) 11%, transparent); }
.nimble-sheet button.ns-add:hover { background: color-mix(in srgb, var(--ns-accent) 20%, transparent); }
.nimble-sheet button.ns-add.is-big { height: 2.2rem; padding: 0 0.95rem; background: var(--interactive-accent); color: var(--text-on-accent); }
.nimble-sheet button.ns-add.is-big:hover { background: var(--interactive-accent-hover); }
.nimble-sheet .ns-add svg { width: 14px; height: 14px; }
.nimble-sheet .ns-none { padding: 0.6rem 0.15rem; font-size: 0.85rem; color: var(--text-muted); }

/* Rows: weapons, spells, features, items */
/* A divider between rows of a list, none under the last: the section ends cleanly. */
.nimble-sheet .ns-row ~ .ns-row, .nimble-sheet .ns-jump ~ .ns-jump { border-top: 1px solid var(--background-modifier-border); }
.nimble-sheet .ns-row-main { display: flex; align-items: center; gap: 0.5rem; min-height: 2.9rem; }
.nimble-sheet .ns-row-toggle { flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 0.05rem; padding: 0.4rem 0.1rem; text-align: left; }
.nimble-sheet button.ns-row-toggle { padding: 0.4rem 0.1rem; }
.nimble-sheet .ns-row-title { display: flex; flex-wrap: wrap; align-items: center; gap: 0.3rem; min-width: 0; max-width: 100%; }
.nimble-sheet .ns-row-name { font-weight: 700; font-size: 0.95rem; overflow: hidden; text-overflow: ellipsis; }
.nimble-sheet .ns-row-detail { font-size: 0.78rem; color: var(--text-muted); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-sheet .ns-tag { font-size: 0.62rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; padding: 0.05rem 0.4rem; border-radius: 999px; background: var(--ns-soft); color: var(--text-muted); white-space: nowrap; }
.nimble-sheet .ns-tag.is-draft, .nimble-cmp-draft { background: color-mix(in srgb, #e08a1e 18%, transparent); color: #c06f0a; }
.theme-dark .nimble-sheet .ns-tag.is-draft, .theme-dark .nimble-cmp-draft { color: #f0a640; }
.nimble-sheet .ns-row-chev { display: inline-flex; color: var(--text-faint); transition: transform 0.15s ease; }
.nimble-sheet .ns-row-chev svg { width: 15px; height: 15px; }
.nimble-sheet .ns-row.is-open .ns-row-chev { transform: rotate(180deg); }
.nimble-sheet .ns-row-right { display: flex; align-items: center; gap: 0.35rem; flex: 0 0 auto; }
.nimble-sheet .ns-row-body { padding: 0.1rem 0.15rem 0.75rem; font-size: 0.88rem; }
.nimble-sheet .ns-row-body .nimble-cmp-text:first-child { margin-top: 0.2rem; }
.nimble-sheet .ns-row-actions { display: flex; justify-content: flex-end; margin-top: 0.4rem; }
.nimble-sheet .ns-remove { font-size: 0.78rem; color: var(--text-error); padding: 0.2rem 0.4rem; border-radius: 6px; }
.nimble-sheet button.ns-remove { padding: 0.2rem 0.4rem; }
.nimble-sheet button.ns-remove:hover { background: color-mix(in srgb, var(--text-error) 10%, transparent); }
.nimble-sheet .ns-roll {
	display: inline-flex; align-items: center; gap: 0.3rem; height: 2.1rem; padding: 0 0.75rem; border-radius: 999px;
	font-weight: 800; font-size: 0.86rem; font-variant-numeric: tabular-nums; white-space: nowrap; color: var(--text-accent);
}
.nimble-sheet button.ns-roll { padding: 0 0.75rem; background: color-mix(in srgb, var(--ns-accent) 13%, transparent); border: 1px solid color-mix(in srgb, var(--ns-accent) 30%, transparent); }
.nimble-sheet button.ns-roll:hover { background: var(--interactive-accent); color: var(--text-on-accent); }
.nimble-sheet button.ns-roll.is-cast { color: var(--ns-mana); background: color-mix(in srgb, var(--ns-mana) 12%, transparent); border-color: color-mix(in srgb, var(--ns-mana) 32%, transparent); }
.nimble-sheet button.ns-roll.is-cast:hover { background: var(--ns-mana); color: #fff; }
.nimble-sheet button.ns-roll.is-short { opacity: 0.5; }
.nimble-sheet .ns-roll-icon { display: inline-flex; }
.nimble-sheet .ns-roll-icon svg { width: 14px; height: 14px; }
.nimble-sheet .ns-equip, .nimble-sheet .ns-equip-spacer { width: 2rem; height: 2rem; flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; border-radius: 8px; color: var(--text-faint); }
.nimble-sheet button.ns-equip { border: 1.5px dashed var(--background-modifier-border-hover); }
.nimble-sheet button.ns-equip:hover { color: var(--text-normal); }
.nimble-sheet button.ns-equip.is-on { border: 1.5px solid var(--ns-accent); background: color-mix(in srgb, var(--ns-accent) 14%, transparent); color: var(--text-accent); }
.nimble-sheet .ns-equip svg { width: 16px; height: 16px; }
.nimble-sheet .ns-qty { display: inline-flex; align-items: center; gap: 0.25rem; }
.nimble-sheet .ns-qty-n { min-width: 1.4rem; text-align: center; font-weight: 800; font-variant-numeric: tabular-nums; }

/* Inventory head: slots and coins */
.nimble-sheet .ns-inv-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.6rem; margin-top: 0.6rem; }
.nimble-sheet .ns-slots { display: flex; align-items: center; gap: 0.5rem; flex: 1 1 12rem; }
.nimble-sheet .ns-slots-bar { flex: 1; height: 0.5rem; border-radius: 999px; background: var(--ns-soft); border: 1px solid var(--background-modifier-border); overflow: hidden; }
.nimble-sheet .ns-slots-fill { height: 100%; width: var(--ns-fill, 0%); background: var(--ns-accent); border-radius: inherit; }
.nimble-sheet .ns-slots.is-over .ns-slots-fill { background: var(--text-error); }
.nimble-sheet .ns-slots-text { font-weight: 800; font-size: 0.86rem; font-variant-numeric: tabular-nums; }
.nimble-sheet .ns-slots.is-over .ns-slots-text { color: var(--text-error); }
.nimble-sheet .ns-coins { display: flex; gap: 0.3rem; }
.nimble-sheet .ns-coin { display: inline-flex; align-items: baseline; gap: 0.2rem; height: 1.9rem; padding: 0 0.6rem; border-radius: 999px; }
.nimble-sheet button.ns-coin { padding: 0 0.6rem; border: 1px solid var(--background-modifier-border); background: var(--ns-soft); line-height: 1.9rem; }
.nimble-sheet button.ns-coin:hover { border-color: var(--ns-accent); }
.nimble-sheet .ns-coin-value { font-weight: 800; font-variant-numeric: tabular-nums; }
.nimble-sheet .ns-coin-label { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; }
.nimble-sheet .ns-coin.is-gp .ns-coin-label { color: var(--ns-gold); }
.nimble-sheet .ns-coin.is-sp .ns-coin-label { color: #8d99a6; }
.nimble-sheet .ns-coin.is-cp .ns-coin-label { color: #b8703a; }

/* Notes tab */
.nimble-sheet .ns-langs { padding: 0.5rem 0 0.2rem; }
.nimble-sheet .ns-details { display: grid; grid-template-columns: repeat(auto-fill, minmax(9rem, 1fr)); gap: 0.4rem 1rem; padding: 0.5rem 0.1rem; }
.nimble-sheet .ns-detail { display: flex; flex-direction: column; font-size: 0.9rem; }
.nimble-sheet .ns-detail-label { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); }
.nimble-sheet .ns-jump { display: flex; align-items: center; gap: 0.4rem; width: 100%; padding: 0.55rem 0.15rem; font-weight: 600; text-align: left; }
.nimble-sheet button.ns-jump { padding: 0.55rem 0.15rem; }
.nimble-sheet button.ns-jump:hover { color: var(--text-accent); }
.nimble-sheet .ns-jump svg { width: 14px; height: 14px; color: var(--text-faint); }

/* Rest & level bar */
/* Camp: a button in the hero card; a dialog with Field rest, Safe rest and Level up */
.ns-camp-dialog.modal { width: min(46rem, calc(100vw - 2rem)); }
.ns-camp-dialog .modal-content { padding-top: 0.25rem; }
.ns-camp-dialog .ns-camp-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0.75rem; }
@media (max-width: 620px) { .ns-camp-dialog .ns-camp-grid { grid-template-columns: minmax(0, 1fr); } }
.ns-camp-dialog button.ns-camp-card {
	--camp-c: var(--interactive-accent);
	position: relative; display: flex; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 0.9rem;
	width: 100%; height: auto; min-height: 11rem; padding: 1rem; text-align: left; white-space: normal; cursor: pointer; overflow: hidden;
	border-radius: 16px; border: 1px solid var(--background-modifier-border); box-shadow: none;
	background: radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--camp-c) 14%, transparent), transparent 70%), var(--background-secondary);
	transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}
.ns-camp-dialog button.ns-camp-card.is-field { --camp-c: #e8743b; }
.ns-camp-dialog button.ns-camp-card.is-safe { --camp-c: #5b7cfa; }
.ns-camp-dialog button.ns-camp-card:hover:not(:disabled) { transform: translateY(-2px); border-color: color-mix(in srgb, var(--camp-c) 60%, transparent); box-shadow: 0 8px 22px color-mix(in srgb, var(--camp-c) 18%, transparent); }
.ns-camp-dialog button.ns-camp-card:disabled { opacity: 0.5; cursor: default; }
.ns-camp-dialog button.ns-camp-card.is-level {
	color: #fff; border-color: transparent;
	background: radial-gradient(120% 100% at 100% 0%, color-mix(in srgb, #fff 22%, transparent), transparent 60%),
		linear-gradient(150deg, color-mix(in srgb, var(--interactive-accent) 85%, #fff), color-mix(in srgb, var(--interactive-accent) 80%, #000));
}
.ns-camp-dialog .ns-camp-card-head { display: flex; align-items: center; gap: 0.6rem; }
.ns-camp-dialog .ns-camp-card-icon {
	flex: 0 0 auto; display: flex; align-items: center; justify-content: center; width: 2.3rem; height: 2.3rem; border-radius: 11px;
	background: color-mix(in srgb, var(--camp-c) 18%, transparent); color: var(--camp-c);
}
.ns-camp-dialog .ns-camp-card-icon svg { width: 18px; height: 18px; }
.ns-camp-dialog .is-level .ns-camp-card-icon { background: rgba(255, 255, 255, 0.2); color: #fff; }
.ns-camp-dialog .ns-camp-card-title { font-size: 1.05rem; font-weight: 800; letter-spacing: -0.01em; }
.ns-camp-dialog .ns-camp-card-body { display: flex; flex-direction: column; gap: 0.5rem; margin-top: auto; }
.ns-camp-dialog .ns-camp-line { font-size: 0.8rem; color: var(--text-muted); }
.ns-camp-dialog .is-level .ns-camp-line { color: rgba(255, 255, 255, 0.85); }
.ns-camp-dialog .ns-camp-dice { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem; color: #e8743b; }
.ns-camp-dialog .ns-die { color: #e8743b; }
.ns-camp-dialog .ns-camp-more { font-size: 0.75rem; font-weight: 700; color: var(--text-muted); }
.ns-camp-dialog .ns-camp-changes { display: flex; flex-direction: column; gap: 0.3rem; }
.ns-camp-dialog .ns-camp-change { display: flex; align-items: center; gap: 0.4rem; font-size: 0.82rem; }
.ns-camp-dialog .ns-camp-change-icon { display: inline-flex; color: var(--camp-c); }
.ns-camp-dialog .ns-camp-change-icon svg { width: 14px; height: 14px; }
.ns-camp-dialog .ns-camp-change-label { flex: 1; color: var(--text-muted); }
.ns-camp-dialog .ns-camp-change-value { font-weight: 800; font-variant-numeric: tabular-nums; }
.ns-camp-dialog .ns-camp-levels { display: flex; align-items: center; gap: 0.5rem; font-size: 2.4rem; font-weight: 800; line-height: 1; font-variant-numeric: tabular-nums; }
.ns-camp-dialog .ns-camp-level-from { opacity: 0.6; }
.ns-camp-dialog .ns-camp-level-arrow { display: inline-flex; opacity: 0.8; }
.ns-camp-dialog .ns-camp-level-arrow svg { width: 24px; height: 24px; }
@media (max-width: 620px) {
	.ns-camp-dialog button.ns-camp-card { min-height: 0; flex-direction: row; align-items: center; justify-content: space-between; }
	.ns-camp-dialog .ns-camp-card-body { margin-top: 0; align-items: flex-end; text-align: right; }
	.ns-camp-dialog .ns-camp-levels { font-size: 1.6rem; }
	.ns-camp-dialog .ns-camp-dice { justify-content: flex-end; }
}
.nimble-sheet .ns-rest-icon { display: inline-flex; }
.nimble-sheet .ns-rest-icon svg { width: 16px; height: 16px; }

/* Dialogs opened from the sheet: rests, conditions, coins, languages, numbers */
.nimble-sheet-dialog.ns-small-dialog { width: min(420px, 94vw); }
.nimble-sheet-dialog.ns-condition-dialog { width: min(520px, 94vw); }
.nimble-sheet-dialog .popover-body, .nimble-sheet-dialog .ns-dialog-body { color: var(--text-muted); line-height: 1.45; }
.nimble-sheet-dialog .ns-dialog-note { color: var(--text-muted); font-size: 0.85rem; margin-top: 0.6rem; }
.nimble-sheet-dialog .popover-row { display: flex; align-items: center; flex-wrap: wrap; gap: 0.5rem; margin-top: 0.75rem; }
.nimble-sheet-dialog .ns-rest-row { justify-content: center; gap: 1rem; margin: 0.9rem 0; }
.nimble-sheet-dialog .ns-rest-n { font-weight: 800; font-size: 1.2rem; min-width: 6rem; text-align: center; font-variant-numeric: tabular-nums; }
.nimble-sheet-dialog .ns-step {
	width: 2.3rem; height: 2.3rem; display: inline-flex; align-items: center; justify-content: center; padding: 0;
	border-radius: 50%; color: var(--text-muted); background: var(--background-modifier-hover); box-shadow: none;
}
.nimble-sheet-dialog .ns-step svg { width: 16px; height: 16px; }
.nimble-sheet-dialog .ns-rest-actions button, .nimble-sheet-dialog .ns-coin-buttons button { flex: 1; }
.nimble-sheet-dialog.ns-number-pop input, .nimble-sheet-dialog .ns-number-pop input, .nimble-sheet-dialog .ns-lang-pop input { flex: 1; min-width: 0; width: 100%; }
.nimble-sheet-dialog .ns-lang-pop .condition-grid, .nimble-sheet-dialog .condition-picker .condition-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(8.5rem, 1fr)); gap: 0.35rem; margin-top: 0.75rem; max-height: 50vh; overflow: auto; }
.nimble-sheet-dialog .condition-option { justify-content: flex-start; font-size: 0.85rem; height: auto; min-height: 2.2rem; padding: 0.3rem 0.6rem; }
.nimble-sheet-dialog .condition-option.is-applied { background: var(--interactive-accent); color: var(--text-on-accent); }
.nimble-sheet-dialog .condition-search, .nimble-sheet-dialog .ns-lang-pop input { width: 100%; }
.nimble-sheet-dialog .ns-rest-changes { display: grid; grid-template-columns: auto auto auto auto; justify-content: start; align-items: center; gap: 0.45rem 0.8rem; margin-top: 0.8rem; }
.nimble-sheet-dialog .ns-rest-change { display: grid; grid-template-columns: subgrid; grid-column: 1 / -1; align-items: center; }
.nimble-sheet-dialog .ns-rest-label { font-size: 0.72rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-muted); }
.nimble-sheet-dialog .ns-rest-from { font-variant-numeric: tabular-nums; color: var(--text-muted); }
.nimble-sheet-dialog .ns-rest-to { font-variant-numeric: tabular-nums; font-weight: 800; }
.nimble-sheet-dialog .ns-rest-arrow { display: inline-flex; color: var(--text-faint); }
.nimble-sheet-dialog .ns-rest-arrow svg { width: 14px; height: 14px; }
.nimble-sheet-dialog .ns-rest-change.is-same .ns-rest-to { font-weight: 500; color: var(--text-muted); }

/* Notes that hold a sheet hide their Properties box; the sheet's button shows it */
.nimble-sheet-note:not(.nimble-show-props) { --metadata-display-editing: none; --metadata-display-reading: none; }
body .workspace-leaf-content .nimble-sheet-note:not(.nimble-show-props) .metadata-container { display: none; }
/* The sheet's header is the title. */
.nimble-sheet-note .inline-title { display: none; }

/* Touch: bigger targets */
@media (pointer: coarse) {
	.nimble-sheet .ns-step { width: 2.1rem; height: 2.1rem; }
	.nimble-sheet .ns-skill-step .ns-step { width: 1.6rem; height: 1.6rem; }
	.nimble-sheet .ns-roll { height: 2.4rem; }
	.nimble-sheet .ns-row-main { min-height: 3.2rem; }
	.nimble-sheet .ns-equip, .nimble-sheet .ns-equip-spacer { width: 2.3rem; height: 2.3rem; }
	.nimble-sheet .ns-cond-x { width: 1.8rem; height: 1.8rem; }
}

/* Character panel */
.nimble-character-view { padding: 0.5rem 0.75rem 1.5rem; }
.nimble-character-view .nimble-sheet { margin-top: 0.5rem; }
.nimble-character-bar { display: flex; align-items: center; gap: 0.3rem; padding-bottom: 0.4rem; border-bottom: 1px solid var(--background-modifier-border); }
.nimble-character-pick { flex: 1; min-width: 0; display: flex; align-items: center; gap: 0.4rem; justify-content: flex-start; font-weight: 600; box-shadow: none; background: transparent; }
.nimble-character-pick > span:nth-child(2) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-character-pick svg { width: 15px; height: 15px; }
.nimble-character-pick-chev { margin-left: auto; color: var(--text-faint); display: inline-flex; }
.nimble-character-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 0.5rem; padding: 2.5rem 1rem; color: var(--text-muted); }
.nimble-character-empty-icon svg { width: 34px; height: 34px; color: var(--text-faint); }
.nimble-character-empty-title { font-weight: 700; font-size: 1.05rem; color: var(--text-normal); }
.nimble-character-empty-body { font-size: 0.86rem; max-width: 18rem; }

/* Compendium card: the card modal, the hover preview, the Compendium tab's page and the dialog's preview.
   The sheet's rows and the level-up dialog show the same body (renderHitBody) without the head.
   Inside a card, spacing comes from the flex gaps; paragraphs drop their own margins there. */
.nimble-cmp-card { display: flex; flex-direction: column; gap: 1rem; min-width: 0; }
.nimble-cmp-head { display: flex; flex-direction: column; gap: 0.3rem; padding-bottom: 0.9rem; border-bottom: 1px solid var(--background-modifier-border); }
.nimble-cmp-kind { display: flex; align-items: center; gap: 0.35rem; margin-bottom: 0.1rem; font-size: 0.7rem; font-weight: 800; line-height: normal; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-accent); }
.nimble-cmp-kind-icon { display: flex; flex: 0 0 auto; }
.nimble-cmp-kind-icon svg { width: 0.9rem; height: 0.9rem; }
.nimble-cmp-card.kind-condition .nimble-cmp-kind { color: #d0613c; }
.theme-dark .nimble-cmp-card.kind-condition .nimble-cmp-kind { color: #ec8a68; }
.nimble-cmp-name { font-size: 1.5rem; font-weight: 800; line-height: 1.2; letter-spacing: -0.01em; color: var(--text-normal); overflow-wrap: anywhere; }
.nimble-cmp-detail { font-size: 0.88rem; line-height: 1.45; color: var(--text-muted); }
.nimble-cmp-body, .nimble-cmp-page { display: flex; flex-direction: column; gap: 0.8rem; min-width: 0; }
.nimble-cmp-tagline { font-size: 1.02em; font-weight: 600; line-height: 1.5; }

/* Facts: label/value chips that wrap with room between the rows. */
.nimble-cmp-facts { display: flex; flex-wrap: wrap; gap: 0.4rem; margin: 0.3rem 0 0.5rem; }
.nimble-cmp-fact { display: inline-flex; align-items: baseline; gap: 0.4rem; max-width: 100%; padding: 0.25rem 0.6rem; border-radius: 6px; background: var(--background-modifier-hover); font-size: 0.82rem; line-height: 1.35; }
.nimble-cmp-fact-label { flex: 0 0 auto; font-size: 0.64rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); }
.nimble-cmp-fact-value { min-width: 0; font-weight: 600; }

/* Rules text */
.nimble-cmp-text { margin: 0.5rem 0; line-height: 1.6; }
.nimble-cmp-list { margin: 0.35rem 0 0.5rem; padding-left: 1.3rem; line-height: 1.55; }
.nimble-cmp-list > li + li { margin-top: 0.3rem; }
:is(.nimble-cmp-body, .nimble-cmp-page, .nimble-cmp-details-body) > :is(.nimble-cmp-text, .nimble-cmp-list, .nimble-cmp-facts, .nimble-cmp-details) { margin: 0; }

/* Where it's from: a footnote under the text. */
.nimble-cmp-source { display: flex; flex-wrap: wrap; align-items: center; gap: 0.4rem; margin-top: 0.35rem; font-size: 0.75rem; line-height: normal; color: var(--text-faint); }
.nimble-cmp-body > .nimble-cmp-source { margin-top: 0.1rem; }
.nimble-cmp-draft { display: inline-flex; align-items: center; height: 1.1rem; padding: 0 0.4rem; border-radius: 999px; font-size: 0.62rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; margin-left: 0.35rem; }
.nimble-cmp-source .nimble-cmp-draft { margin-left: 0; }

.nimble-cmp-link { color: var(--text-accent); text-decoration: none; cursor: pointer; }
.nimble-cmp-link:hover { text-decoration: underline; }
.nimble-cmp-fact .nimble-cmp-link.nimble-cmp-fact-value { color: var(--text-accent); }

/* The card modal: room around the card, a Back bar when you've followed a link, the action under a rule. */
.modal.nimble-cmp-modal { width: min(600px, 94vw); }
/* Class and subclass pages are long: wider, and the content scrolls under a fixed modal frame (phones keep Obsidian's full-screen sheet). */
body:not(.is-phone) .modal.nimble-cmp-modal { max-height: 88vh; padding: 0; }
body:not(.is-phone) .modal.nimble-cmp-modal.is-page { width: min(760px, 94vw); }
.nimble-cmp-modal .modal-content { min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
body:not(.is-phone) .nimble-cmp-modal .modal-header { display: none; }
body:not(.is-phone) .nimble-cmp-modal .modal-content { margin: 0; padding: 1.5rem 1.75rem 1.75rem; }
body:not(.is-phone) .nimble-cmp-modal .nimble-cmp-head { padding-right: 1.5rem; }
.nimble-cmp-modal .modal-close-button { z-index: 2; }
.nimble-cmp-nav { display: flex; align-items: center; min-width: 0; margin-bottom: 1rem; }
/* Desktop: a full-width bar across the top of the modal, level with the close button, that stays while the page scrolls.
   (A sticky box stops at the scroller's padding, so `top` cancels the content's top padding.) */
body:not(.is-phone) .nimble-cmp-nav { position: sticky; top: -1.5rem; z-index: 1; margin: -1.5rem -1.75rem 1.1rem; padding: 0.35rem 3rem 0.5rem 1.25rem; background: var(--modal-background, var(--background-primary)); border-bottom: 1px solid var(--background-modifier-border); }
button.nimble-cmp-back { display: inline-flex; align-items: center; gap: 0.35rem; max-width: 100%; height: 1.75rem; padding: 0 0.75rem 0 0.55rem; border-radius: 999px; background: var(--background-modifier-hover); box-shadow: none; color: var(--text-muted); font-size: 0.8rem; font-weight: 600; line-height: normal; cursor: pointer; }
button.nimble-cmp-back:hover { background: var(--background-modifier-active-hover, var(--background-modifier-hover)); color: var(--text-normal); }
.nimble-cmp-back-icon { display: flex; flex: 0 0 auto; }
.nimble-cmp-back-icon svg { width: 14px; height: 14px; }
.nimble-cmp-back-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nimble-cmp-modal .nimble-cmp-actions { display: flex; justify-content: flex-end; gap: 0.5rem; margin-top: 1.25rem; }

/* Class pages */
.nimble-cmp-highlights { margin-top: 0.1rem; }
.nimble-cmp-section-title { margin: 0.7rem 0 -0.25rem; padding-bottom: 0.35rem; border-bottom: 1px solid var(--background-modifier-border); font-size: 0.72rem; font-weight: 800; line-height: normal; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); }
.nimble-cmp-levels { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.nimble-cmp-level { display: grid; grid-template-columns: 2rem minmax(0, 1fr); gap: 0.75rem; padding: 0.7rem 0; border-bottom: 1px solid var(--background-modifier-border-hover, var(--background-modifier-border)); }
.nimble-cmp-level:first-child { padding-top: 0.2rem; }
.nimble-cmp-level:last-child { border-bottom: none; padding-bottom: 0; }
.nimble-cmp-level-badge { display: flex; align-items: center; justify-content: center; width: 1.8rem; height: 1.8rem; border-radius: 50%; background: color-mix(in srgb, var(--interactive-accent) 16%, transparent); color: var(--text-accent); font-size: 0.82rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.nimble-cmp-level-features { display: flex; flex-direction: column; gap: 0.7rem; min-width: 0; padding-top: 0.15rem; }
.nimble-cmp-feature .nimble-cmp-text { margin: 0.2rem 0 0.4rem; }
.nimble-cmp-feature .nimble-cmp-text:last-child { margin-bottom: 0; }
.nimble-cmp-feature-head { display: flex; flex-wrap: wrap; align-items: center; gap: 0.4rem; line-height: 1.4; }
.nimble-cmp-feature-name { font-weight: 700; }
.nimble-cmp-feature.is-placeholder .nimble-cmp-feature-name { font-weight: 600; color: var(--text-muted); }
.nimble-cmp-feature.is-placeholder .nimble-cmp-text { color: var(--text-muted); font-size: 0.9em; }
.nimble-cmp-tag { display: inline-flex; align-items: center; padding: 0.05rem 0.45rem; border-radius: 999px; background: var(--background-modifier-hover); color: var(--text-muted); font-size: 0.7rem; font-weight: 700; line-height: 1.5; white-space: nowrap; }
.nimble-cmp-tag.is-req { background: color-mix(in srgb, #e08a1e 14%, transparent); }

/* Collapsible sections (About …, option groups, subclasses, spell list, FAQ): a framed row that opens downward. */
.nimble-cmp-details { overflow: hidden; border: 1px solid var(--background-modifier-border); border-radius: 8px; }
.nimble-cmp-details + .nimble-cmp-details { margin-top: 0.5rem; }
.nimble-cmp-summary { display: flex; align-items: center; gap: 0.5rem; min-height: 2.6rem; padding: 0.5rem 0.9rem 0.5rem 0.65rem; cursor: pointer; font-weight: 700; line-height: 1.35; list-style: none; }
.nimble-cmp-summary::-webkit-details-marker { display: none; }
.nimble-cmp-summary:hover { background: var(--background-modifier-hover); }
.nimble-cmp-summary:focus-visible { outline: 2px solid var(--interactive-accent); outline-offset: -2px; }
.nimble-cmp-details[open] > .nimble-cmp-summary { border-bottom: 1px solid var(--background-modifier-border); }
.nimble-cmp-summary-chev { display: flex; flex: 0 0 auto; color: var(--text-faint); transition: transform 0.15s ease; }
.nimble-cmp-summary-chev svg { width: 16px; height: 16px; }
.nimble-cmp-details[open] > .nimble-cmp-summary .nimble-cmp-summary-chev { transform: rotate(90deg); }
.nimble-cmp-summary-title { min-width: 0; }
.nimble-cmp-count { margin-left: auto; padding: 0.05rem 0.45rem; border-radius: 999px; background: var(--background-modifier-hover); color: var(--text-muted); font-size: 0.7rem; font-weight: 700; line-height: 1.5; font-variant-numeric: tabular-nums; }
.nimble-cmp-details-body { display: flex; flex-direction: column; gap: 0.7rem; padding: 0.85rem 1rem 1rem; }
.nimble-cmp-group .nimble-cmp-feature { padding-top: 0.7rem; border-top: 1px dashed var(--background-modifier-border); }
.nimble-cmp-group .nimble-cmp-details-body > .nimble-cmp-feature:first-child { padding-top: 0; border-top: none; }
.nimble-cmp-subclass-flavor { font-style: italic; line-height: 1.55; color: var(--text-muted); }
.nimble-cmp-group-about { margin-top: 0.5rem; font-size: 0.92em; }
.nimble-cmp-spell-list { margin: 0; line-height: 1.7; }
.nimble-cmp-faq-item + .nimble-cmp-faq-item { padding-top: 0.7rem; border-top: 1px dashed var(--background-modifier-border); }
.nimble-cmp-faq-q { font-weight: 700; line-height: 1.45; }
.nimble-cmp-faq-item .nimble-cmp-text { margin: 0.25rem 0 0; }

/* In the hover preview: a little wider for cards, a little tighter, and the card scrolls within the preview's max height. */
.nimble-hover-preview.is-compendium { width: min(460px, calc(100vw - 24px)); overscroll-behavior: contain; }
.nimble-hover-preview.is-compendium .hover-preview-body { padding: 0.9rem 1rem 1rem; }
.nimble-hover-preview.is-compendium .nimble-cmp-card { gap: 0.8rem; }
.nimble-hover-preview.is-compendium .nimble-cmp-head { padding-bottom: 0.75rem; }
.nimble-hover-preview.is-compendium .nimble-cmp-name { font-size: 1.25rem; }
.nimble-hover-preview.is-compendium :is(.nimble-cmp-body, .nimble-cmp-page) { gap: 0.7rem; }

/* The card, as Nimble's books and sheet set it (design study: #nimble/compendium): a page framed in the sheet's
   charcoal like the campaign cards, the kind over the name in Vollkorn heavy italic, the detail line in the
   condensed face, facts as the sheet's chips (each label kept with its value), rules text as the stat block sets
   it (boxed dice, dotted rules words), run-in names in Vollkorn, khaki ribbons over a class page's sections and
   charcoal level boxes. A class or subclass page carries its name between the class's scrollwork. Scoped to the
   card: the sheet's rows and the level-up dialog show the same body in their own dress. */
.nimble-cmp-card.ev-sys-nimble, .ev-sys-nimble .nimble-cmpx-page.nimble-cmp-card {
	gap: 14px;
	padding: 18px 20px 16px;
	border-radius: 4px;
	background: var(--ev-surface);
	box-shadow: inset 0 0 0 2px var(--ev-bar);
	color: var(--ev-text);
	font: 500 14.5px/21px var(--ev-font-ui);
	container-type: inline-size;
}
.nimble-cmp-card .nimble-cmp-head { gap: 2px; padding: 0; border: 0; }
.nimble-cmp-card .nimble-cmp-kind { gap: 6px; margin: 0 0 2px; font: 700 11.5px/16px var(--ev-font-ui); letter-spacing: 0.08em; color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-kind-icon svg { width: 14px; height: 14px; }
.nimble-cmp-card.kind-condition .nimble-cmp-kind, .theme-dark .nimble-cmp-card.kind-condition .nimble-cmp-kind { color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-name { font: italic 900 30px/1.12 var(--ev-font-name); letter-spacing: 0; color: var(--ev-text); text-wrap: balance; overflow-wrap: break-word; }
.nimble-cmp-card .nimble-cmp-detail { margin-top: 2px; font: 700 15px/20px var(--ev-font-display); color: var(--ev-text); }
.nimble-cmp-card :is(.nimble-cmp-body, .nimble-cmp-page) { gap: 12px; }
/* The class's scrollwork carries the page's name (the sheet's class panel heading, a size up). */
.nimble-cmp-card .nimble-cmp-name.ns-scroll { margin: 2px 0 0; padding: 4px 0 0; }
.nimble-cmp-card .nimble-cmp-scroll .ns-scroll-title { top: 1px; flex: 0 1 auto; min-width: 0; font: italic 900 28px/34px var(--ev-font-name); font-variant: small-caps; letter-spacing: 0.02em; white-space: normal; text-align: center; text-wrap: balance; }
.nimble-cmp-card .nimble-cmp-tagline { font: 700 15px/20px var(--ev-font-display); text-align: center; }
/* Facts: the sheet's chips, each label kept with its value; a spell's mana in blue, links underlined quietly. */
.nimble-cmp-card .nimble-cmp-facts { gap: 6px; margin: 0; }
.nimble-cmp-card .nimble-cmp-fact { align-items: center; gap: 7px; min-height: 28px; padding: 4px 9px; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); color: var(--ev-chip-text); }
.nimble-cmp-card .nimble-cmp-fact-label { font: 700 11px/normal var(--ev-font-ui); letter-spacing: 0.06em; color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-fact-value { font: 600 13.5px/18px var(--ev-font-ui); }
.nimble-cmp-card .nimble-cmp-fact.is-mana .nimble-cmp-fact-value { color: var(--ev-mana); }
.nimble-cmp-card .nimble-cmp-link, .nimble-cmp-card .nimble-cmp-fact .nimble-cmp-link.nimble-cmp-fact-value { color: var(--ev-text); text-decoration: none; box-shadow: inset 0 -1.5px 0 var(--ev-line-strong); }
.nimble-cmp-card .nimble-cmp-link:hover { box-shadow: inset 0 -1.5px 0 currentColor; }
/* Rules text: the stat block's measure, rolls boxed, rules words dotted, a run-in name in Vollkorn. */
.nimble-cmp-card .nimble-cmp-text { line-height: 21px; }
.nimble-cmp-card .nimble-cmp-text > strong:first-child { font: italic 900 15px/21px var(--ev-font-name); }
.nimble-cmp-card .nimble-cmp-list { padding-left: 20px; line-height: 21px; }
.nimble-cmp-card .nimble-dice { padding: 0 3px; border-radius: 3px; box-shadow: inset 0 0 0 1px var(--ev-line-strong); background: var(--ev-surface); color: inherit; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
.nimble-cmp-card .nimble-dice.is-clickable { border-bottom: 0; color: inherit; }
.nimble-cmp-card .nimble-dice.is-clickable:hover, .nimble-cmp-card .nimble-dice.is-clickable:focus-visible { background: var(--ev-surface-2); box-shadow: inset 0 0 0 1px var(--ev-text-2); }
.nimble-cmp-card :is(.ev-term, .nimble-condition-ref) { border-bottom: 1.5px dotted var(--ev-text-2); border-radius: 0; }
.nimble-cmp-card :is(.ev-term, .nimble-condition-ref):hover { border-bottom-color: currentColor; background: none; }
/* Where it's from, and a playtest draft as a tag (dark, white text). */
.nimble-cmp-card .nimble-cmp-source { gap: 8px; margin-top: 0; font: 500 12px/16px var(--ev-font-ui); color: var(--ev-text-2); }
:is(.nimble-cmp-card, .nimble-spotlight) .nimble-cmp-draft { display: inline-flex; align-items: center; height: 18px; margin-left: 6px; padding: 0 6px; border-radius: var(--ev-r-chip, 3px); background: var(--ev-bar, var(--ev-accent)); color: var(--ev-on-bar, var(--ev-on-accent)); font: 700 10.5px/normal var(--ev-font-ui, var(--font-interface)); letter-spacing: 0.05em; text-transform: uppercase; }
.nimble-cmp-card .nimble-cmp-source .nimble-cmp-draft { margin-left: 0; }
/* A class page: khaki ribbons over its sections, a charcoal box for each level, feature names in Vollkorn. */
.nimble-cmp-card .nimble-cmp-section-title { margin: 6px 0 0; padding: 5px 10px 4px; border: 0; border-radius: 2px; background: var(--ev-band); color: var(--ev-band-text); font: italic 900 15px/19px var(--ev-font-name); letter-spacing: 0; text-transform: none; }
.nimble-cmp-card .nimble-cmp-level { grid-template-columns: 30px minmax(0, 1fr); gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--ev-line); }
.nimble-cmp-card .nimble-cmp-level:first-child { padding-top: 4px; }
.nimble-cmp-card .nimble-cmp-level-badge { width: 30px; height: 30px; border-radius: var(--ev-r-sm); background: var(--ev-bar); color: var(--ev-on-bar); font: 700 16px/normal var(--ev-font-num); font-variant-numeric: lining-nums tabular-nums; }
.nimble-cmp-card .nimble-cmp-level-features { gap: 10px; padding-top: 4px; }
.nimble-cmp-card .nimble-cmp-feature-head { gap: 6px; line-height: 21px; }
.nimble-cmp-card .nimble-cmp-feature-name { font: italic 900 15.5px/21px var(--ev-font-name); }
.nimble-cmp-card .nimble-cmp-feature.is-placeholder .nimble-cmp-feature-name { font-weight: 700; color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-feature.is-placeholder .nimble-cmp-text { color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-tag { height: 20px; padding: 0 6px; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); color: var(--ev-chip-text); font: 600 11.5px/normal var(--ev-font-ui); }
.nimble-cmp-card .nimble-cmp-tag.is-req { background: transparent; box-shadow: inset 0 0 0 1px var(--ev-line-strong); color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-summary .nimble-cmp-tag { background: var(--ev-bar); color: var(--ev-on-bar); font-weight: 700; font-size: 10.5px; letter-spacing: 0.05em; text-transform: uppercase; }
.nimble-cmp-card .nimble-cmp-highlights { margin: 0; }
/* Collapsible sections (option groups, subclasses, the spell list, FAQ): a framed row that opens downward. */
.nimble-cmp-card .nimble-cmp-details { border: 0; border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line-strong); }
.nimble-cmp-card .nimble-cmp-details + .nimble-cmp-details { margin-top: 0; }
.nimble-cmp-card .nimble-cmp-summary { gap: 8px; min-height: 40px; padding: 8px 12px 8px 10px; }
.nimble-cmp-card .nimble-cmp-summary:hover { background: var(--ev-surface-2); }
.nimble-cmp-card .nimble-cmp-summary:focus-visible { outline: 2px solid var(--ev-accent); }
.nimble-cmp-card .nimble-cmp-details[open] > .nimble-cmp-summary { border-bottom: 1px solid var(--ev-line); }
.nimble-cmp-card .nimble-cmp-summary-chev { color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-summary-chev svg { width: 14px; height: 14px; }
.nimble-cmp-card .nimble-cmp-summary-title { position: relative; top: 1px; font: italic 900 15px/20px var(--ev-font-name); } /* Vollkorn's capitals sit 1.1px high in a centred box (measured) */
.nimble-cmp-card .nimble-cmp-count { display: inline-flex; align-items: center; height: 20px; padding: 0 7px; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); color: var(--ev-chip-text); font: 600 12px/normal var(--ev-font-ui); }
.nimble-cmp-card .nimble-cmp-details-body { gap: 10px; padding: 12px 14px 14px; }
.nimble-cmp-card .nimble-cmp-group .nimble-cmp-feature { padding-top: 10px; border-top: 1px solid var(--ev-line); }
.nimble-cmp-card .nimble-cmp-subclass-flavor { color: var(--ev-text-2); }
.nimble-cmp-card .nimble-cmp-faq-item + .nimble-cmp-faq-item { border-top: 1px solid var(--ev-line); }
.nimble-cmp-card .nimble-cmp-faq-q { font: italic 900 15px/21px var(--ev-font-name); }
@container (max-width: 420px) {
	.nimble-cmp-card .nimble-cmp-name { font-size: 25px; }
	.nimble-cmp-card .nimble-art-slot { width: 56px; height: 56px; }
	.nimble-cmp-card .nimble-cmp-scroll .ns-scroll-title { font-size: 22px; line-height: 28px; }
}
/* A homebrew block frames the card itself (the note's card, homebrew-block.ts): the card inside drops its own frame. */
.nimble-homebrew.ev-sys-nimble > .nimble-cmp-card { padding: 0; border-radius: 0; background: none; box-shadow: none; }
/* In a hover preview the card is the page: a little tighter. */
.nimble-hover-preview .nimble-cmp-card.ev-sys-nimble { padding: 14px 16px 12px; }
.nimble-hover-preview .nimble-cmp-card .nimble-cmp-name { font-size: 24px; }
/* The card's dialog: on the game's paper, the card framed on it. */
.modal.nimble-cmp-modal.ev-sys-nimble { background: var(--ev-bg); }
body:not(.is-phone) .modal.nimble-cmp-modal.ev-sys-nimble .modal-content { padding: 1.25rem; }
body:not(.is-phone) .modal.nimble-cmp-modal.ev-sys-nimble .nimble-cmp-nav { top: -1.25rem; margin: -1.25rem -1.25rem 1rem; background: var(--ev-bg); border-bottom-color: var(--ev-line); }
body:not(.is-phone) .modal.nimble-cmp-modal.ev-sys-nimble .nimble-cmp-head { padding-right: 2rem; }
.modal.nimble-cmp-modal.ev-sys-nimble button.nimble-cmp-back { border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line-strong); color: var(--ev-text); font: 500 13px/normal var(--ev-font-ui); }
.modal.nimble-cmp-modal.ev-sys-nimble button.nimble-cmp-back:hover { background: var(--ev-surface-2); }

/* Spotlight: compendium rows and the picker's filter chips */
.nimble-spotlight .nimble-spot-meta.is-text { font-size: 0.74rem; color: var(--text-faint); -webkit-line-clamp: 2; }
.nimble-spotlight .suggestion-item.is-taken { opacity: 0.6; }
.nimble-spotlight .nimble-spotlight-chips { display: flex; align-items: center; flex-wrap: wrap; gap: 0.3rem; padding: 0.5rem 0.75rem; border-bottom: 1px solid var(--background-modifier-border); }
.nimble-spotlight .nimble-spotlight-title { width: 100%; font-size: 0.72rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); margin-bottom: 0.1rem; }
.nimble-spotlight .nimble-spotlight-chip { height: 1.75rem; padding: 0 0.7rem; border-radius: 999px; font-size: 0.78rem; font-weight: 600; box-shadow: none; background: var(--background-secondary); border: 1px solid var(--background-modifier-border); color: var(--text-muted); }
.nimble-spotlight .nimble-spotlight-chip:hover { color: var(--text-normal); border-color: var(--interactive-accent); }
.nimble-spotlight .nimble-spotlight-chip.is-active { background: var(--interactive-accent); border-color: var(--interactive-accent); color: var(--text-on-accent); }

/* ---------- Nimble's character wizard (character-wizard.ts): New character and Level up ----------
   A game dialog (core/dialog.ts) on Nimble's paper: step chips along the top, one decision a step in a carousel,
   the sheet's own stat boxes and save triangles, names in Vollkorn, labels in the condensed capitals, tags dark
   with white text. Colour has its jobs: red for HP, blue for spells, ochre for the class's own things (key stats,
   the subclass chosen), charcoal for everything else. */
.modal.ev-dialog.nimble-wizard { width: min(820px, 96vw); height: min(760px, 92vh); max-height: 92vh; display: flex; flex-direction: column; overflow: hidden; }
.nimble-wizard .modal-content { flex: 1 1 auto; min-height: 0; gap: 0; overflow: hidden; }
.nimble-wizard .modal-title { padding-right: 30px; }
.nimble-wizard .lu-sub { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 10px; min-height: 24px; margin: -4px 0 10px; color: var(--ev-text-2); font: 600 13.5px/normal var(--ev-font-ui); }
.nimble-wizard .lu-badge { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 9px; border-radius: var(--ev-r-chip); background: var(--ev-bar); color: var(--ev-on-bar); font: 700 15px/normal var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; }
.nimble-wizard .lu-badge-from { opacity: 0.7; }
.nimble-wizard .lu-badge-arrow { display: inline-flex; }
.nimble-wizard .lu-badge-arrow svg { display: block; width: 12px; height: 12px; }
body.is-phone .nimble-wizard .lu-sub { justify-content: center; }
.nimble-wizard .lu-level-tag { height: 22px; padding: 0 8px; border-radius: var(--ev-r-chip); background: var(--ev-bar); color: var(--ev-on-bar); font: 700 12px/normal var(--ev-font-display); letter-spacing: 0.06em; text-transform: uppercase; }

/* Step chips: where you are, what's done */
.nimble-wizard .lu-dots { display: flex; flex: 0 0 auto; gap: 6px; padding: 2px 1px 10px; overflow-x: auto; scrollbar-width: none; border-bottom: 1px solid var(--ev-line); }
.nimble-wizard .lu-dots::-webkit-scrollbar { display: none; }
.nimble-wizard button.lu-dot { flex: 0 0 auto; height: 30px; padding: 0 11px; border: 1px solid var(--ev-line-strong); border-radius: 999px; background: var(--ev-surface); box-shadow: none; color: var(--ev-text-2); font: 600 12.5px/normal var(--ev-font-ui); white-space: nowrap; cursor: pointer; --ev-pill-icon: 14px; --ev-pill-gap: 6px; }
.nimble-wizard button.lu-dot:hover { color: var(--ev-text); }
.nimble-wizard button.lu-dot.is-done { color: var(--ev-text); }
.nimble-wizard button.lu-dot.is-done .ev-pill-icon { color: var(--ev-ok); }
.nimble-wizard button.lu-dot.is-active { border-color: var(--ev-accent); background: var(--ev-accent); color: var(--ev-on-accent); }
.nimble-wizard button.lu-dot.is-active .ev-pill-icon { color: inherit; }

/* The carousel: the dialog keeps its height; a long step scrolls inside itself */
.nimble-wizard .lu-viewport { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; }
.nimble-wizard .lu-track { display: flex; align-items: stretch; height: 100%; transform: translateX(calc(var(--lu-at, 0) * -100%)); transition: transform 0.38s cubic-bezier(0.2, 0.8, 0.2, 1); }
.nimble-wizard .lu-track.no-anim { transition: none; }
.nimble-wizard .lu-panel { flex: 0 0 100%; min-width: 0; height: 100%; box-sizing: border-box; padding: 14px 2px 18px; overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; opacity: 0.25; transition: opacity 0.3s ease; container: lu / inline-size; }
.nimble-wizard .lu-panel.is-active { opacity: 1; }
.nimble-wizard .lu-panel.is-shake { animation: lu-shake 0.4s ease; }
@keyframes lu-shake { 20%, 60% { transform: translateX(-6px); } 40%, 80% { transform: translateX(6px); } }
.nimble-wizard .ev-dialog-foot { flex: 0 0 auto; margin-top: 0; padding-top: 12px; border-top: 1px solid var(--ev-line); }

/* Step heads, labels and tags */
.nimble-wizard .lu-step-head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; margin-bottom: 12px; }
.nimble-wizard .lu-step-title { flex: 1 1 auto; min-width: 0; font: italic 800 21px/1.2 var(--ev-font-name); color: var(--ev-text); }
.nimble-wizard .lu-count { height: 24px; padding: 0 9px; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); color: var(--ev-chip-text); font: 700 14px/normal var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; --ev-pill-icon: 13px; --ev-pill-gap: 4px; }
.nimble-wizard .lu-count.is-done { background: var(--ev-bar); color: var(--ev-on-bar); }
.nimble-wizard .lu-section-label { margin: 16px 0 8px; }
.nimble-wizard .lu-tag { height: 20px; padding: 0 7px; border-radius: var(--ev-r-chip); background: var(--ev-bar); color: var(--ev-on-bar); font: 700 11px/normal var(--ev-font-display); letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; --ev-pill-icon: 11px; --ev-pill-gap: 4px; }
.nimble-wizard .lu-tag.is-quiet { background: var(--ev-chip-bg); color: var(--ev-chip-text); }
.nimble-wizard .lu-tag.is-light { background: rgb(255 255 255 / 0.18); color: #fff; }
.nimble-wizard .lu-tag.is-count { background: var(--ev-ochre-fill); color: #fff; }
.nimble-wizard .lu-tag.is-school { background: var(--ev-mana-fill); color: #fff; }
.nimble-wizard :is(.lu-intro, .lu-from) { margin-bottom: 10px; font-size: 13.5px; line-height: 1.45; color: var(--ev-text-2); }
.nimble-wizard .lu-empty { margin-top: 6px; font-size: 13.5px; font-style: italic; color: var(--ev-text-2); }
.nimble-wizard .lu-warn { padding: 8px 10px; border-radius: var(--ev-r-md); background: var(--ev-danger-bg); color: var(--ev-danger-text); font: 600 13px/1.35 var(--ev-font-ui); }
.nimble-wizard :is(button.lu-reset, button.lu-skill-reset, button.lu-option-less, button.lu-compare-choose, button.lu-view-btn) { height: 30px; padding: 0 11px; border: 1px solid var(--ev-line-strong); border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: none; color: var(--ev-text); font: 600 13px/normal var(--ev-font-ui); cursor: pointer; --ev-pill-icon: 14px; --ev-pill-gap: 6px; }
.nimble-wizard :is(button.lu-reset, button.lu-skill-reset, button.lu-option-less, button.lu-compare-choose, button.lu-view-btn):hover { background: var(--ev-surface-2); }

/* Hero: the form, the class at a glance, the gear */
.nimble-wizard .lu-form { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 14px; }
.nimble-wizard .lu-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.nimble-wizard .lu-field.is-wide { grid-column: 1 / -1; }
.nimble-wizard :is(input.lu-input, select.lu-select) { width: 100%; height: 38px; border-radius: var(--ev-r-md); font: 500 14.5px/normal var(--ev-font-ui); }
.nimble-wizard input.lu-name-input { height: 42px; font: italic 800 19px/normal var(--ev-font-name); }
.nimble-wizard .lu-level-keys { display: flex; align-items: center; gap: 6px; }
.nimble-wizard input.lu-level-input { width: 58px; height: 40px; padding: 0; border-radius: var(--ev-r-md); text-align: center; font: 700 19px/normal var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; }
.nimble-wizard .lu-field-note { font-size: 12.5px; color: var(--ev-text-2); }
.nimble-wizard .lu-field-note.is-warn { color: var(--ev-danger-text); font-weight: 600; }
.nimble-wizard .lu-class { margin-top: 16px; padding: 12px 14px; border-radius: var(--ev-r-lg); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line); }
.nimble-wizard .lu-class-top { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; margin-bottom: 10px; }
.nimble-wizard .lu-class-name { font: italic 900 20px/1.15 var(--ev-font-name); }
.nimble-wizard .lu-class-tagline { font-size: 13px; color: var(--ev-text-2); }
.nimble-wizard .lu-facts { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px 12px; }
.nimble-wizard .lu-fact { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.nimble-wizard .lu-fact.is-wide { grid-column: span 2; }
.nimble-wizard .lu-fact-label { font: 700 11.5px/normal var(--ev-font-display); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
.nimble-wizard .lu-fact-value { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 24px; font: 600 14px/1.35 var(--ev-font-ui); color: var(--ev-text); }
.nimble-wizard .lu-fact-value .ns-die { width: 22px; height: 22px; color: var(--ev-bar-2); }
.nimble-wizard .lu-fact-icon { display: inline-flex; }
.nimble-wizard .lu-fact-icon svg { display: block; width: 16px; height: 16px; }
.nimble-wizard .lu-fact-icon.is-hp { color: var(--ev-hp); }
.nimble-wizard .lu-key-tag { height: 22px; padding: 0 7px; border-radius: var(--ev-r-chip); background: var(--ev-ochre-fill); color: #fff; font: 700 13px/normal var(--ev-font-num); letter-spacing: 0.04em; }
.nimble-wizard .lu-save { display: inline-flex; align-items: center; gap: 4px; font: 700 14px/normal var(--ev-font-num); }
.nimble-wizard svg.lu-tri { display: block; width: 15px; height: 7px; overflow: visible; }
.nimble-wizard svg.lu-tri path { fill: var(--ev-bar); stroke: var(--ev-bar); stroke-width: 1.5; stroke-linejoin: round; }
.nimble-wizard .lu-gear { margin-top: 16px; }
.nimble-wizard .lu-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.nimble-wizard .lu-chip { height: 28px; padding: 0 10px; border: 0; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); box-shadow: none; color: var(--ev-chip-text); font: 600 13px/normal var(--ev-font-ui); --ev-pill-icon: 14px; --ev-pill-gap: 6px; }
.nimble-wizard button.lu-chip { cursor: pointer; }
