.nimble-wizard .lu-key-mark { height: 16px; text-align: center; font: 700 11.5px/16px var(--ev-font-display); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ev-ochre); }
.nimble-wizard .lu-place-notes { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin-top: 10px; }

/* Overview and features */
.nimble-wizard .lu-gains { display: flex; flex-wrap: wrap; gap: 6px; }
