.nimble-wizard .lu-features { display: flex; flex-direction: column; gap: 8px; }
.nimble-wizard .lu-feature { padding: 10px 12px; border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line); }
.nimble-wizard .lu-feature-top { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; }
.nimble-wizard .lu-feature-name { font: italic 800 16px/1.25 var(--ev-font-name); color: var(--ev-text); }
.nimble-wizard .lu-feature-text { margin-top: 4px; font-size: 13.5px; line-height: 1.5; color: var(--ev-text); }
.nimble-wizard .lu-feature-text .nimble-cmp-text { margin: 0; }

/* Hit points: roll ▲, the flat bonus, or what you rolled at the table */
.nimble-wizard .lu-hp-options { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.nimble-wizard .lu-hp-option { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; min-height: 150px; padding: 14px 10px; border-radius: var(--ev-r-lg); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line-strong); text-align: center; cursor: pointer; transition: box-shadow var(--ev-dur) ease; }
.nimble-wizard .lu-hp-option:hover { box-shadow: inset 0 0 0 1px var(--ev-text-2); }
.nimble-wizard .lu-hp-option:focus-visible { outline: 2px solid var(--ev-ochre); outline-offset: 2px; }
.nimble-wizard .lu-hp-option.is-picked { box-shadow: inset 0 0 0 2px var(--ev-accent); }
.nimble-wizard .lu-hp-option.is-invalid { box-shadow: inset 0 0 0 2px var(--ev-danger-text); }
.nimble-wizard .lu-hp-icon { display: inline-flex; color: var(--ev-text-2); }
.nimble-wizard .lu-hp-icon svg { display: block; width: 22px; height: 22px; }
.nimble-wizard .lu-hp-title { font: 700 14px/normal var(--ev-font-ui); }
.nimble-wizard .lu-hp-value { font: 700 30px/1 var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; color: var(--ev-hp); }
.nimble-wizard input.lu-hp-input { width: 92px; height: 40px; text-align: center; font: 700 20px/normal var(--ev-font-num); }
.nimble-wizard .lu-hp-more { position: absolute; top: 6px; right: 6px; }
