.nimble-wizard .lu-hp-arrow { display: inline-flex; color: var(--ev-text-2); }
.nimble-wizard .lu-hp-arrow svg { display: block; width: 16px; height: 16px; }
.nimble-wizard .lu-hp-bar { display: flex; height: var(--ev-bar-h, 8px); border-radius: var(--ev-bar-r, 2px); background: var(--ev-track-empty); overflow: hidden; }
.nimble-wizard .lu-hp-bar-old { width: var(--w); background: var(--ev-hp); }
.nimble-wizard .lu-hp-bar-new { width: var(--w); background: color-mix(in srgb, var(--ev-hp) 45%, var(--ev-surface)); transition: width 0.4s ease; }

/* Subclass: a tab for each, one on show using the step (or every one side by side) */
.nimble-wizard .lu-view-toggle { display: inline-flex; }
.nimble-wizard .lu-view-toggle > button.lu-view-btn { border-radius: 0; }
