.nimble-wizard .lu-view-toggle > button.lu-view-btn:last-child { margin-left: -1px; border-radius: 0 var(--ev-r-md) var(--ev-r-md) 0; }
.nimble-wizard .lu-view-toggle > button.lu-view-btn.is-on { border-color: var(--ev-accent); background: var(--ev-accent); color: var(--ev-on-accent); }
.nimble-wizard .lu-sub-tabs { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
.nimble-wizard button.lu-sub-tab { height: 32px; padding: 0 12px; border: 1px solid var(--ev-line-strong); border-radius: 999px; background: var(--ev-surface); box-shadow: none; color: var(--ev-text-2); font: italic 800 14.5px/normal var(--ev-font-name); cursor: pointer; --ev-pill-icon: 14px; --ev-pill-gap: 5px; }
.nimble-wizard button.lu-sub-tab > .ev-pill-text { position: relative; top: 1px; } /* Vollkorn's capitals sit high in its line box */
.nimble-wizard button.lu-sub-tab:hover { color: var(--ev-text); }
.nimble-wizard button.lu-sub-tab.is-chosen { border-color: var(--ev-ochre); color: var(--ev-text); }
.nimble-wizard button.lu-sub-tab.is-chosen .ev-pill-icon { color: var(--ev-ochre); }
.nimble-wizard button.lu-sub-tab.is-active { border-color: var(--ev-accent); background: var(--ev-accent); color: var(--ev-on-accent); }
