.nimble-wizard .lu-sub-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 6px; }
.nimble-wizard button.lu-sub-band-choose { height: 34px; padding: 0 13px; border: 1px solid rgb(255 255 255 / 0.55); border-radius: var(--ev-r-md); background: rgb(255 255 255 / 0.12); box-shadow: none; color: #fff; font: 700 13.5px/normal var(--ev-font-ui); cursor: pointer; --ev-pill-icon: 15px; --ev-pill-gap: 6px; }
.nimble-wizard button.lu-sub-band-choose:hover { background: rgb(255 255 255 / 0.22); }
.nimble-wizard button.lu-sub-band-choose.is-chosen { border-color: var(--ev-ochre-fill); background: var(--ev-ochre-fill); }
.nimble-wizard .lu-sub-flavor { grid-column: 1 / -1; font-size: 14px; font-style: italic; line-height: 1.45; opacity: 0.9; }
.nimble-wizard .lu-complexity { display: inline-flex; align-items: center; gap: 3px; }
.nimble-wizard .lu-complexity-label { margin-right: 3px; font: 700 11px/normal var(--ev-font-display); letter-spacing: 0.07em; text-transform: uppercase; opacity: 0.85; }
.nimble-wizard .lu-pip { width: 8px; height: 8px; border: 1.5px solid currentColor; border-radius: 50%; opacity: 0.55; }
.nimble-wizard .lu-pip.is-on { background: currentColor; opacity: 1; }
.nimble-wizard .lu-sub-body { display: flex; flex-direction: column; gap: 10px; padding: 12px 16px 14px; }
.nimble-wizard .lu-sub-intro { font-size: 13.5px; line-height: 1.5; }
.nimble-wizard .lu-sub-levels { display: flex; flex-direction: column; gap: 8px; }
.nimble-wizard .lu-sub-level { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; border-radius: var(--ev-r-md); background: var(--ev-surface-2); }
.nimble-wizard .lu-sub-level.is-now { background: var(--ev-ochre-soft); }
.nimble-wizard .lu-sub-level-head { display: flex; align-items: center; gap: 6px; }
.nimble-wizard .lu-now-pill { background: var(--ev-ochre-fill); }
