.nimble-wizard .lu-sub-body .nimble-cmp-source { font-size: 12px; color: var(--ev-text-2); }
.nimble-wizard .lu-compare { overflow: auto; max-height: 100%; border-radius: var(--ev-r-lg); box-shadow: inset 0 0 0 1px var(--ev-line); }
.nimble-wizard .lu-compare table { min-width: 100%; border-collapse: separate; border-spacing: 0; font-size: 13px; }
.nimble-wizard .lu-compare :is(th, td) { min-width: 190px; padding: 8px 10px; border-bottom: 1px solid var(--ev-line); vertical-align: top; text-align: left; }
.nimble-wizard .lu-compare thead th { position: sticky; top: 0; z-index: 1; background: var(--ev-surface); }
.nimble-wizard .lu-compare .lu-compare-corner, .nimble-wizard .lu-compare .lu-compare-level { position: sticky; left: 0; z-index: 2; width: 44px; min-width: 44px; background: var(--ev-surface); font: 700 15px/normal var(--ev-font-num); }
.nimble-wizard .lu-compare .lu-compare-corner { font: 700 11.5px/normal var(--ev-font-display); letter-spacing: 0.07em; text-transform: uppercase; color: var(--ev-text-2); }
.nimble-wizard .lu-compare tr.is-now :is(td, th) { background: var(--ev-ochre-soft); }
.nimble-wizard .lu-compare td.is-chosen { background: color-mix(in srgb, var(--ev-ochre) 10%, var(--ev-surface)); }
.nimble-wizard .lu-compare-name { font: italic 800 15px/1.2 var(--ev-font-name); }
.nimble-wizard button.lu-compare-choose { margin-top: 6px; height: 28px; }
.nimble-wizard button.lu-compare-choose.is-chosen { border-color: var(--ev-ochre-fill); background: var(--ev-ochre-fill); color: #fff; }

/* Picks, spells and the Epic Boon: a card each */
