.nimble-wizard .lu-options.is-compact { margin-top: 6px; }
.nimble-wizard .lu-option { position: relative; display: flex; flex-direction: column; gap: 4px; padding: 10px 12px; border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line-strong); cursor: pointer; transition: box-shadow var(--ev-dur) ease; }
.nimble-wizard .lu-option:hover { box-shadow: inset 0 0 0 1px var(--ev-text-2); }
.nimble-wizard .lu-option:focus-visible { outline: 2px solid var(--ev-ochre); outline-offset: 2px; }
.nimble-wizard .lu-option.is-chosen { box-shadow: inset 0 0 0 2px var(--ev-accent); }
.nimble-wizard .lu-option.is-dim { opacity: 0.72; }
.nimble-wizard .lu-option.is-taken { opacity: 0.55; cursor: default; }
.nimble-wizard .lu-option-top { display: flex; align-items: center; gap: 6px; }
.nimble-wizard .lu-option-name { flex: 1 1 auto; min-width: 0; font: italic 800 15.5px/1.25 var(--ev-font-name); }
.nimble-wizard .lu-option-tags { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 4px; }
.nimble-wizard .lu-option-check { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; width: 20px; height: 20px; border-radius: 50%; background: var(--ev-accent); color: var(--ev-on-accent); }
.nimble-wizard .lu-option-check svg { display: block; width: 12px; height: 12px; }
.nimble-wizard .lu-option-req { font: 600 12px/normal var(--ev-font-ui); color: var(--ev-text-2); }
.nimble-wizard .lu-option-text { font-size: 13px; line-height: 1.45; }
.nimble-wizard .lu-option-text .nimble-cmp-text { margin: 0; }
.nimble-wizard button.lu-option-less { align-self: flex-start; height: 26px; padding: 0 9px; font-size: 12px; --ev-pill-icon: 12px; --ev-pill-gap: 4px; }
.nimble-wizard :is(.lu-spell-box, .lu-stat-box) { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
.nimble-wizard .lu-spell-label .ev-dialog-label-value { font-variant-numeric: tabular-nums; }

/* Stat increases */
.nimble-wizard .lu-stats { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; }
.nimble-wizard button.lu-stat { display: flex; flex-direction: column; align-items: center; gap: 4px; height: auto; padding: 10px 6px; border: 0; border-radius: var(--ev-r-md); background: var(--ev-surface); box-shadow: inset 0 0 0 1px var(--ev-line-strong); color: var(--ev-text); cursor: pointer; }
.nimble-wizard button.lu-stat:hover { box-shadow: inset 0 0 0 1px var(--ev-text-2); }
.nimble-wizard button.lu-stat.is-chosen { box-shadow: inset 0 0 0 2px var(--ev-accent); }
.nimble-wizard .lu-stat-key { font: 700 14px/normal var(--ev-font-num); letter-spacing: 0.05em; }
.nimble-wizard .lu-stat-nums { display: inline-flex; align-items: center; gap: 5px; font: 700 18px/normal var(--ev-font-num); font-variant-numeric: tabular-nums lining-nums; }
.nimble-wizard .lu-stat-old { color: var(--ev-text-2); }
.nimble-wizard .lu-stat-arrow { display: inline-flex; color: var(--ev-text-2); }
.nimble-wizard .lu-stat-arrow svg { display: block; width: 13px; height: 13px; }

/* Skills */
.nimble-wizard .lu-skill-status { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.nimble-wizard :is(.lu-skill-budget, .lu-skill-move) { height: 26px; padding: 0 9px; border-radius: var(--ev-r-chip); background: var(--ev-chip-bg); color: var(--ev-chip-text); font: 700 12.5px/normal var(--ev-font-ui); --ev-pill-icon: 13px; --ev-pill-gap: 5px; }
.nimble-wizard .lu-skill-budget.is-open { background: var(--ev-bar); color: var(--ev-on-bar); }
.nimble-wizard .lu-skill-move.is-used { opacity: 0.6; }
.nimble-wizard button.lu-skill-reset { height: 26px; font-size: 12.5px; --ev-pill-icon: 13px; }
.nimble-wizard .lu-heroic { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; margin-bottom: 10px; padding: 8px 10px; border-radius: var(--ev-r-md); background: var(--ev-surface-2); }
