.nimble-wizard .lu-skill-row.is-down { background: var(--ev-surface-2); }
.nimble-wizard .lu-skill-label { display: flex; align-items: baseline; gap: 8px; min-width: 0; }
.nimble-wizard .lu-skill-stat { font: 600 11px/normal var(--ev-font-num); letter-spacing: 0.06em; color: var(--ev-bar-2); }
.nimble-wizard .lu-skill-name { overflow: hidden; font: 600 14px/normal var(--ev-font-ui); text-overflow: ellipsis; white-space: nowrap; }
