.nimble-wizard .lu-review-value { font: 600 14px/1.35 var(--ev-font-ui); overflow-wrap: anywhere; }

/* Level up's moment: the level pops in, confetti behind it */
.nimble-wizard.is-celebrating .modal-title { display: none; }
.nimble-wizard .lu-celebrate { position: relative; display: flex; flex: 1 1 auto; align-items: center; justify-content: center; min-height: 320px; }
.nimble-wizard .lu-confetti { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.nimble-wizard .lu-celebrate-inner { position: relative; display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 20px; text-align: center; }
.nimble-wizard .lu-celebrate-level { display: grid; place-items: center; width: 96px; height: 96px; border-radius: 50%; background: var(--ev-bar); box-shadow: 0 0 0 4px var(--ev-ochre); color: var(--ev-on-bar); font: 700 48px/1 var(--ev-font-num); animation: lu-pop 0.6s var(--ev-ease); }
