.ev-dialog.ev-sys-nimble .ev-dialog-label-text { font: 700 12.5px/normal var(--ev-font-display); letter-spacing: 0.07em; }
.ev-dialog.ev-sys-dnd5e .ev-dialog-label-text { font: 600 15px/normal var(--ev-font-display); font-variant: small-caps; text-transform: none; letter-spacing: 0.04em; color: var(--ev-accent-text); }
.ev-dialog .ev-dialog-label-value { display: inline-flex; align-items: center; line-height: normal; font: 600 13px/normal var(--ev-font-ui, var(--font-interface)); color: var(--ev-text, var(--text-normal)); }
