.ev-dialog button.ev-dialog-btn { height: 40px; min-width: 0; padding: 0 16px; border-radius: var(--ev-r-md, 6px); font: 600 14px/normal var(--ev-font-ui, var(--font-interface)); --ev-pill-icon: 17px; --ev-pill-gap: 7px; }
