.nimble-roll-dialog .rd-expr { font: 700 26px/30px var(--ev-font-num, var(--font-interface)); font-variant-numeric: tabular-nums lining-nums; letter-spacing: -0.01em; color: var(--ev-text, var(--text-normal)); overflow-wrap: anywhere; }
