.nimble-entity-builder button.eb-df-die:hover:not(:disabled) { background: var(--background-modifier-hover); }
.nimble-entity-builder button.eb-df-die:disabled { padding-right: 0.6rem; opacity: 1; cursor: default; }
.nimble-entity-builder .eb-df-plus { display: inline-flex; align-items: center; padding: 0 0.1rem 0 0.55rem; border-left: 1px solid var(--ev-paper-edge); color: var(--text-muted); font-weight: 700; }
.nimble-entity-builder .eb-df-plus + .eb-df-seg { border-left: 0; }
.nimble-entity-builder .eb-df-plus + .eb-df-seg input.eb-df-num { padding-left: 0.15rem; }
.nimble-entity-builder .eb-dice-avg { display: inline-flex; align-items: center; gap: 0.5rem; margin-left: auto; font-size: 0.8rem; }
.nimble-entity-builder button.eb-book-reset { gap: 0.3rem; border: 0; cursor: var(--cursor-link, pointer); }
.nimble-entity-builder .eb-book-reset-icon { display: inline-flex; }
.nimble-entity-builder .eb-book-reset-icon svg { width: 12px; height: 12px; }
.nimble-entity-builder button.eb-book-reset:hover { filter: brightness(1.1); box-shadow: 0 0 0 1px currentColor inset; }
body.is-mobile .nimble-entity-builder .eb-dicefield { height: 2.75rem; }
